    "help.13": "也可关闭过滤默认，使用以下按钮分别筛选：默认好评 / 默认差评 / 只看自主填写",
    "help.14": "「模板阈值」有什么用",
    "help.15": "默认阈值为 8。未知文案去掉部分标点和空白后，重复次数达到阈值、长度不少于 12 个字符，且至少 90% 的评级一致时，推测为模板。已知模板不受频次阈值限制。",
    "help.16": "频次规则可以帮助发现未收录的候选模板，但无法单凭重复次数确认其官方来源。",
    "help.17": "降低阈值只会提高未知文案的识别敏感度，也更容易将玩家重复用语误判为模板；不影响已知模板匹配。",
    "help.18": "调高更保守：只认超大面积的重复，漏掉的模板会被当普通评论统计。",
    "help.19": "改完立刻重算，不用重新抓数据。",
    "help.20": "便签",
    "help.21": "评论卡片右上角的 ☆ 点一下就收进「便签」页。可以附一段自己的备注，点「定位」会跳回评论列表并高亮那一条。便签连同评论快照一起存下来——就算原评论被删了，便签里照样看得到内容。",
    "help.22": "同步快不快",
