    "help.24": "全量重抓最多并行运行 6 条楼层分片流和一条热门流。耗时和完整度取决于网络、评论数量及接口返回，不保证固定时间或 100% 覆盖。",
    "help.25": "楼中楼（评论下面的回复）",
    "help.26": "评论底下的回复会一并抓到并显示，但可能不全。原因是接口本身：",
    "help.27": "时间排序可能遗漏部分评论，不同接口返回的子回复数量也可能不同。",
