    "help.29": "我试过专门的 sub_replies 接口：参数能通过校验（不再报「参数无效」），但服务端一律返回 fatal error，可能要求登录态，也可能还差一个挖不到的字段。",
    "help.30": "同一评论从不同排序返回时，会更新评论字段，并保留返回过的较完整子回复。接口未返回的内容仍可能缺失，不能保证子回复完整。",
    "help.31": "时间区间筛选",
    "help.32": "两个日期框均包含当天，可只填起点或终点。摘要显示匹配数量和区间。「清除」仅清空日期条件，关键词、评级等其他筛选保留。",
    "help.33": "关掉网页会怎样",
