    "help.1": "評級：好評 / 負評",
    "help.2": "直接用介面的 is_recommend 欄位，那是遊戲裡的好評/負評本身，不是猜的。千星奇域只有好評和負評兩個選項，沒有中性評價。",
    "help.3": "is_recommend=true 表示好評，false 表示負評。官方好評率取自關卡介面；未提供時顯示本機好評率，兩者統計範圍可能不同。",
    "help.4": "預設評論是什麼",
    "help.5": "只提交好評或負評而不填寫文字時，遊戲可能代發預設文案，因此會出現大量相同留言。範例：",
    "help.6": "非常優秀的奇域，推薦大家遊玩~（中文·好評）　奇域仍有待打磨，期待作者的更新~（中文·負評）",
    "help.7": "預設文案沒有玩家自行填寫的詳細意見，但好評或負評仍可能反映真實選擇。隱藏範本有助於閱讀具體建議，不應將這些評價一概視為無效。",
    "help.8": "工具已內建多種語言的已知範本，包括簡體及繁體中文。以下保留部分原文範例：",
    "help.9": "An outstanding Wonderland! Highly recommended for everyone to try~（英）　Потрясающий предел! Настоятельно рекомендуем всем!（俄）　とても素晴らしい幻境ですので、皆さんにもオススメです～（日）",
    "help.10": "未收錄或已變更的文案，會依重複頻次等條件推測為範本；結果可能誤判，請搭配原文確認。",
    "help.11": "「過濾預設」有什麼用",
    "help.12": "隱藏被識別為純範本的留言，保留玩家補充的文字；自動識別可能誤判。",
    "help.13": "也可關閉過濾預設，使用以下按鈕分別篩選：預設好評 / 預設負評 / 只看自行填寫",
    "help.14": "「範本閾值」有什麼用",
    "help.15": "預設門檻為 8。未知文案移除部分標點和空白後，重複次數達到門檻、長度至少 12 個字元，且至少 90% 的評價一致時，推測為範本。已知範本不受頻次門檻限制。",
    "help.16": "頻次規則有助於發現未收錄的候選範本，但不能僅憑重複次數確認官方來源。",
    "help.17": "降低門檻只會提高未知文案的辨識敏感度，也較易將玩家的重複用語誤判；不影響已知範本比對。",
    "help.18": "調高更保守：只認超大面積的重複，漏掉的範本會被當一般評論統計。",
    "help.19": "改完立刻重算，不用重新抓資料。",
    "help.20": "便籤",
    "help.21": "評論卡片右上角的 ☆ 點一下就收進「便籤」頁。可以附一段自己的備註，點「定位」會跳回評論清單並標示那一則。便籤連同評論快照一起存下來——就算原評論被刪了，便籤裡照樣看得到內容。",
    "help.22": "同步快不快",
    "help.23": "同步最新：增量，只找新的。通常 1-2 秒。",
    "help.24": "完整重抓最多同時執行 6 條留言分片及一條熱門流。耗時與完整度取決於網路、留言數量及介面回傳，不保證固定時間或 100% 覆蓋。",
    "help.25": "樓中樓（評論下面的回覆）",
    "help.26": "評論底下的回覆會一併抓到並顯示，但可能不全。原因是介面本身：",
    "help.27": "時間排序可能漏掉部分留言，不同介面回傳的子回覆數量也可能不同。",
    "help.28": "熱門排序可能補回部分漏掉的留言，但子回覆有時只是預覽。",
    "help.29": "我試過專門的 sub_replies 介面：參數能通過驗證（不再報「參數無效」），但伺服端一律回傳 fatal error，可能要求登入態，也可能還差一個挖不到的欄位。",
    "help.30": "同一留言由不同排序回傳時，會更新欄位並保留較完整的子回覆。介面未回傳的內容仍可能缺漏，不能保證子回覆完整。",
    "help.31": "時間區間篩選",
    "help.32": "兩個日期欄均包含當天，可只填起點或終點。摘要顯示符合數量及區間。「清除」只清空日期，關鍵字與評價等其他條件保留。",
    "help.33": "關掉網頁會怎樣",
    "help.34": "預設啟動器會隱藏主控台。啟用自動退出時，正常關閉頁面約 3 秒後背景服務退出；異常關閉由心跳逾時處理。可在「管理」頁切換常駐模式。",
    "app.title": "奇域評論收集器",
    "tpl.explain": "此處彙整已知範本及高頻重複文案。頻次識別屬於推測：降低門檻更敏感，也較易誤判；提高門檻可能漏判。「範本＋補充文字」保留了玩家內容，視為自行填寫。",
    "add.hint1": "米遊社沒有公開的關卡搜尋介面，這裡的做法是繞道：搜貼文 → 從正文裡摳出別人貼的分享連結 → 再換成真名。所以只有「有人貼過分享連結」的關卡才搜得到，搜不到不代表關卡不存在 —— 那就用下面的方式二。",
    "add.hint2": "關卡 ID 怎麼找：打開關卡頁面，網址列裡 level_id=（網頁版）或 id=（遊戲內分享連結）後面那串數字就是。直接把那串數字貼進上面的框也能查，不一定要完整連結。",
    "add.hint3": "貼上完整 HoYoLAB 關卡連結，或先選對伺服器再填 ID。國服及國際服都會先直接連線，失敗後自動尋找系統代理、config/proxy.txt 及本機代理連接埠。工具不提供代理節點。國際服入口使用 ID 或連結查詢。",
