    "lookup.proxyMissing": "直接連線失敗，且找不到可用的本機代理。請啟動代理後重試；目前無法確認 ID 是否有效。",
    "lookup.proxyFailed": "代理存取失敗或遭攔截，未找到可用路線。請檢查代理節點後重試；目前無法確認 ID 是否有效。",
    "lookup.network": "網路請求未完成，無法確認關卡是否存在。請檢查連線後重試。",
    "batch.keepOpen": "匯入後保持視窗開啟",
    "onboard.realIntro": "先選擇熟悉的語言。接著會實際匯入一個關卡的評論，練習標籤篩選、收藏與寫便箋；評論及備註會儲存在本機。可隨時稍後再學。",
    "onboard.importHelp": "選擇正確區服，貼上自己的關卡 ID 或分享連結，查詢確認後新增並同步。簡中預設國服，其他語言預設國際服，皆可手動切換。 停止輸入約半秒後會自動查詢，也可點選查詢或按 Enter。",
    "onboard.syncWait": "正在實際下載評論，請查看主畫面的同步記錄。確認評論已儲存後會繼續教學。",
    "onboard.syncRetry": "首次同步未成功。請查看同步記錄，檢查網路或代理後重試。已登記關卡會保留。",
    "onboard.empty": "同步完成，但未取得可用評論。請換成有評論的關卡或稍後重試；教學尚未完成。",
    "onboard.labelsTitle": "標籤與篩選",
    "onboard.labelsBody": "好評與差評標籤來自官方評級；預設標籤由工具辨識模板，可能誤判。請點選一個篩選按鈕或切換過濾預設，觀察列表後繼續。",
    "onboard.saveTitle": "收藏一則評論",
    "onboard.saveBody": "點選任一評論右上角的 ☆，存入便箋並保留內容快照。再點下一步，教學會確認是否已儲存。",
    "onboard.needStar": "尚未確認便箋已儲存。請點選評論的 ☆，等待儲存後再繼續。",
    "onboard.editTitle": "寫下自己的備註",
    "onboard.editBody": "已開啟剛收藏的便箋。請在標示的卡片中寫下備註，等待自動儲存後點下一步，教學會讀取本機記錄核對。",
    "onboard.waitSave": "請輸入非空白備註，等自動儲存完成後再繼續。",
    "onboard.doneTitle": "已完成首次操作",
    "onboard.doneBody": "已確認評論、便箋與備註儲存在本機。評論頁用於同步與篩選；便箋頁可跨關卡分組、定位與匯出；管理頁可調整分組、查看目錄及常駐設定。",
    "error.entryMissing": "關卡已移除，請重新整理列表。",
