    "error.syncBusy": "同步進行中，請完成後再移除、刪除或新增。",
    "error.storage": "無法讀取或儲存本機資料，請檢查檔案與目錄權限。",
    "error.request": "請求失敗，請檢查本機服務或網路。",
    "error.jobChanged": "同步工作已由其他視窗更新，請重新整理後重試。",
    "onboard.translationTip": "可搭配 Chrome 等瀏覽器的翻譯功能或翻譯擴充功能，將不同語言的評論翻成熟悉的語言，協助理解並整理有效回饋。"
