    "tpl.unclassified": "{src} (unclassified)",
    "help.1": "Rating: positive / negative",
    "help.2": "Taken straight from the is_recommend field — that is the game's own up/down vote, not a guess. Wonderland only has positive and negative, no neutral.",
    "help.3": "is_recommend=true means positive; false means negative. The official positive rating percentage comes from the level API. If unavailable, a local percentage is shown; their populations may differ.",
    "help.4": "What are default comments?",
    "help.5": "When a player submits a positive or negative rating without text, the game may post preset wording. This produces repeated comments such as:",
    "help.6": "非常优秀的奇域，推荐大家游玩~ (zh · positive)　奇域仍有待打磨，期待作者的更新~ (zh · negative)",
    "help.7": "Preset wording contains no player-written detail, but the rating may still reflect a real choice. Hide templates to focus on specific feedback; their ratings are not automatically invalid.",
    "help.8": "Known templates are included for multiple languages, including Simplified and Traditional Chinese. Some original examples follow:",
    "help.9": "An outstanding Wonderland! Highly recommended for everyone to try~ (en)　Потрясающий предел! Настоятельно рекомендуем всем! (ru)　とても素晴らしい幻境ですので、皆さんにもオススメです～ (ja)",
    "help.10": "Unknown or changed wording is classified heuristically using repetition and other conditions. Check the original text when the classification matters.",
    "help.11": "What does \"Hide templates\" do?",
    "help.12": "Hide comments classified as pure templates, retaining player-added text. Automatic classification may be wrong.",
    "help.13": "Leave Hide templates off to inspect each category separately: Positive templates / Negative templates / Player-written only",
    "help.14": "What is the \"template threshold\"?",
    "help.15": "The default threshold is 8. After some punctuation and whitespace are removed, unknown text is treated as a likely template if it repeats at least this often, is at least 12 characters long, and has at least 90% consistent ratings. Known templates do not require this frequency.",
    "help.16": "Frequency rules help find candidate templates not yet listed, but repetition alone does not establish an official source.",
    "help.17": "Lowering the threshold makes unknown-text detection more sensitive and increases false positives from repeated player wording. It does not affect known-template matching.",
    "help.18": "Higher is more conservative: only massive repetition counts, and missed templates are counted as ordinary comments.",
    "help.19": "Recomputed immediately after you change it — no re-crawl needed.",
    "help.20": "Notes",
    "help.21": "Click ☆ at the top-right of a comment card to save it to the Notes tab. You can attach your own remark; \"Go to comment\" jumps back to the list and highlights it. The note stores a snapshot of the comment too — even if the original is deleted, the text is still there.",
    "help.22": "How fast is syncing?",
    "help.23": "Sync latest: incremental, new comments only. Usually 1–2 seconds.",
    "help.24": "Full collection runs up to six comment-number shards and one popularity stream in parallel. Speed and completeness depend on the network, comment count and API responses; neither a fixed duration nor 100% coverage is guaranteed.",
    "help.25": "Replies under comments",
    "help.26": "Replies under comments are fetched and shown as well, but may be incomplete. The reason is the API itself:",
    "help.27": "Chronological sorting may omit some comments, and the number of replies returned can vary between API responses.",
    "help.28": "Popularity sorting may recover some omitted comments, but its replies may be previews only.",
    "help.29": "I tried the dedicated sub_replies endpoint: the parameters pass validation (no more \"invalid parameter\"), but the server always returns a fatal error — it may require a logged-in session, or need one more undiscoverable field.",
    "help.30": "When different sort orders return the same comment, its fields are updated and the more complete replies are retained. Replies omitted by the API may still be missing.",
    "help.31": "Date range filter",
    "help.32": "Both date boundaries include the whole day, and either boundary may be left empty. The summary shows the matching count and range. Clear removes only the date conditions; keywords and rating filters remain.",
    "help.33": "What happens when I close the page?",
    "help.34": "The default launcher hides the console. With automatic exit enabled, closing the page normally stops the background service after about three seconds; heartbeat timeout handles abnormal closure. Persistent mode can be changed on the Manage tab.",
    "app.title": "Wonderland Comment Collector",
    "tpl.explain": "Known templates and frequently repeated wording are grouped here. Frequency detection is heuristic: a lower threshold catches more but risks false positives; a higher one may miss templates. Templates with player-added text count as player-written comments.",
    "add.hint1": "miyoushe exposes no public level search API, so this works around it: search posts → pull shared links out of post bodies → resolve them to real names. Only levels someone has already shared a link for can be found; not finding one does not mean it does not exist — use option 2 below instead.",
    "add.hint2": "How to find the level ID: open the level page and look at the address bar — the number after level_id= (web) or id= (in-game share link) is it. You can paste just that number into the box above; the full link is not required.",
    "add.hint3": "Paste a full HoYoLAB level link, or choose the correct region before entering an ID. Both CN and Global try direct access first, then system proxies, config/proxy.txt and local proxy ports if access fails. This tool does not supply proxy nodes. The Global tab uses IDs or links.",
    "btn.gotIt": "Got it",
    "status.stayOn": "Changed to: exits with the page",
    "status.stayOff": "Background persistent mode enabled; switch back to automatic exit on the Manage tab.",
