    "data.para": "フォルダごとコピーすればそのまま使えます（Node.js が必要）。コメントデータを含めずに渡したい場合は、上の「データ削除」で消すか data フォルダを削除してください。",
    "unit.listSep": "、",
    "grp.current": "（現在）",
    "tpl.unclassified": "{src}（未分類）",
    "help.1": "評価：高評価 / 低評価",
    "help.2": "API の is_recommend フィールドをそのまま使っています。ゲーム内の高評価/低評価そのもので、推測ではありません。千星奇域は高評価と低評価の二択で、中間はありません。",
    "help.3": "is_recommend=true は高評価、false は低評価です。公式高評価率はステージAPIの値です。取得できない場合はローカルの高評価率を表示します。集計対象が異なる場合があります。",
    "help.4": "既定コメントとは",
    "help.5": "高評価または低評価だけを送信し、本文を書かなかった場合、ゲームが定型文を投稿することがあります。そのため、次のような同じ文章が繰り返し表示されます。",
    "help.6": "非常优秀的奇域，推荐大家游玩~（中国語・高評価）　奇域仍有待打磨，期待作者的更新~（中国語・低評価）",
    "help.7": "定型文には具体的な意見は含まれませんが、評価自体はプレイヤーの選択を反映している場合があります。定型文を隠すと具体的な感想を探しやすくなります。評価が無効になるわけではありません。",
    "help.8": "簡体字・繁体字中国語を含む複数言語の既知の定型文を登録済みです。以下は原文の例です。",
    "help.9": "An outstanding Wonderland! Highly recommended for everyone to try~（英）　Потрясающий предел! Настоятельно рекомендуем всем!（露）　とても素晴らしい幻境ですので、皆さんにもオススメです～（日）",
    "help.10": "未登録または変更された文章は、出現頻度などから定型文と推定します。誤判定の可能性があるため、必要に応じて原文を確認してください。",
    "help.11": "「定型文を隠す」の役割",
    "help.12": "定型文のみと判定されたコメントを隠し、プレイヤーの追記は残します。自動判定には誤りがあり得ます。",
    "help.13": "定型文の非表示をオフにして、次の各種類を個別に絞り込めます：定型文の高評価 / 定型文の低評価 / 自由記述のみ",
    "help.14": "「テンプレート閾値」の役割",
    "help.15": "既定のしきい値は8です。一部の記号と空白を除いた未知の文章が、しきい値以上の回数出現し、12文字以上で、評価の90%以上が一致する場合に定型文と推定します。既知の定型文には頻度の条件は適用されません。",
    "help.16": "頻度の条件は未登録の定型文候補の発見に役立ちますが、繰り返しだけでは公式の文章と断定できません。",
    "help.17": "しきい値を下げると未知の文章を検出しやすくなりますが、プレイヤーの同じ表現も誤判定しやすくなります。既知の定型文の照合には影響しません。",
    "help.18": "上げると保守的：大規模な重複だけを認め、漏れたテンプレートは通常コメントとして集計されます。",
    "help.19": "変更すると即座に再計算されます。データの再取得は不要です。",
    "help.20": "メモ",
    "help.21": "コメントカード右上の ☆ を押すと「メモ」タブに保存されます。自分用の覚え書きを添えられ、「コメントへ移動」で一覧に戻ってその 1 件を強調表示します。メモにはコメントのスナップショットも保存されるので、元のコメントが削除されても内容は残ります。",
    "help.22": "同期の速さ",
    "help.23": "最新を同期：差分のみ。通常 1〜2 秒。",
    "help.24": "全件取得は、コメント番号で分割した最大6本の処理と人気順の処理を並行実行します。所要時間と取得率はネットワークやAPIに依存し、一定時間や100%の取得を保証しません。",
    "help.25": "返信（コメント下のリプライ）",
    "help.26": "コメント下の返信も取得して表示しますが、不完全な場合があります。原因は API 側です：",
    "help.27": "時系列順では一部のコメントが返されない場合があります。また、応答によって返信の件数が異なることがあります。",
    "help.28": "人気順で不足するコメントを取得できる場合がありますが、返信はプレビューのみのことがあります。",
    "help.29": "専用の sub_replies エンドポイントも試しました：パラメータは検証を通りますが（「パラメータが無効」は出なくなりました）、サーバーは必ず fatal error を返します。ログイン状態が必要か、さらに不明なフィールドが要るのかもしれません。",
    "help.30": "同じコメントが異なる並び順で返ると、各項目を更新し、より多くの返信を含むデータを保持します。APIが返さない返信は取得できない場合があります。",
    "help.31": "期間フィルター",
    "help.32": "開始日と終了日は当日全体を含み、片方だけの指定も可能です。件数と期間を表示します。クリアは日付条件のみを解除し、キーワードや評価の条件は残します。",
    "help.33": "ページを閉じるとどうなるか",
    "help.34": "通常の起動ではコンソールを表示しません。自動終了が有効なら、ページを正常に閉じて約3秒後にバックグラウンドサービスが終了します。異常終了時はハートビートのタイムアウトで終了します。常駐設定は管理画面で変更できます。",
    "app.title": "奇域コメント収集ツール",
    "tpl.explain": "既知の定型文と頻出する文章をまとめて表示します。頻度による判定は推定です。しきい値を下げると検出は増えますが誤判定も増え、上げると見逃すことがあります。プレイヤーの追記がある定型文は自由記述として扱います。",
    "add.hint1": "miyoushe には公開のステージ検索 API がないため、投稿を検索 → 本文から他人が貼った共有リンクを抜き出す → 実名に解決、という回り道をしています。そのため「誰かが共有リンクを貼った」ステージしか見つかりません。見つからないからといって存在しないとは限りません — 下の方法 2 をお使いください。",
    "add.hint2": "ステージ ID の探し方：ステージページを開き、アドレスバーの level_id=（Web 版）または id=（ゲーム内共有リンク）の後ろの数字がそれです。その数字だけを上の欄に貼っても検索できます（リンク全体でなくても可）。",
    "add.hint3": "HoYoLABのリンク全体を貼り付けるか、サーバーを選択してIDを入力してください。中国版・グローバル版ともに直接接続を試し、失敗した場合はシステムプロキシ、config/proxy.txt、ローカルポートを検索します。プロキシ自体は提供しません。グローバル版の画面ではIDかリンクで検索します。",
    "btn.gotIt": "了解",
    "status.stayOn": "変更しました：ページを閉じると終了",
    "status.stayOff": "バックグラウンド常駐に変更しました。管理画面で自動終了に戻せます。",
