    "data.port": "포트: {port} (127.0.0.1만)",
    "data.para": "폴더째 복사하면 그대로 쓸 수 있습니다(Node.js 필요). 댓글 데이터 없이 넘기려면 위의 \"데이터 삭제\"를 쓰거나 data 폴더를 지우세요.",
    "unit.listSep": ", ",
