    "tpl.unclassified": "{src} (미분류)",
    "help.1": "평가: 긍정 / 부정",
    "help.2": "API의 is_recommend 필드를 그대로 씁니다. 게임 안의 긍정/부정 자체이며 추측이 아닙니다. 천성기역은 긍정과 부정 두 가지만 있고 중립은 없습니다.",
    "help.3": "is_recommend=true는 긍정, false는 부정 평가입니다. 공식 비율은 스테이지 API에서 가져옵니다. 없으면 로컬 비율을 표시하며, 집계 대상은 다를 수 있습니다.",
    "help.4": "기본 댓글이란",
    "help.5": "본문 없이 긍정 또는 부정 평가만 제출하면 게임이 기본 문구를 게시할 수 있습니다. 이 때문에 다음과 같은 내용이 반복됩니다.",
    "help.6": "非常优秀的奇域，推荐大家游玩~ (중국어 · 긍정)　奇域仍有待打磨，期待作者的更新~ (중국어 · 부정)",
    "help.7": "기본 문구에는 구체적인 의견이 없지만, 평가 자체는 플레이어의 실제 선택일 수 있습니다. 구체적인 피드백을 보려면 기본 문구를 숨기세요. 해당 평가가 무효라는 뜻은 아닙니다.",
    "help.8": "중국어 간체와 번체를 포함한 여러 언어의 알려진 기본 문구가 등록되어 있습니다. 다음은 원문 예시입니다.",
    "help.9": "An outstanding Wonderland! Highly recommended for everyone to try~ (영)　Потрясающий предел! Настоятельно рекомендуем всем! (러)　とても素晴らしい幻境ですので、皆さんにもオススメです～ (일)",
    "help.10": "등록되지 않았거나 변경된 문구는 반복 횟수 등의 조건으로 추정합니다. 잘못 분류될 수 있으므로 필요하면 원문을 확인하세요.",
    "help.11": "\"기본 문구 숨기기\"의 역할",
    "help.12": "순수 기본 문구로 분류된 댓글을 숨기고 플레이어의 추가 글은 남깁니다. 자동 분류는 틀릴 수 있습니다.",
    "help.13": "기본 문구 숨기기를 끄고 각 유형을 따로 볼 수 있습니다: 기본 문구 긍정 / 기본 문구 부정 / 직접 작성만",
    "help.14": "\"템플릿 임계값\"의 역할",
    "help.15": "기본 기준값은 8입니다. 일부 문장 부호와 공백을 제거한 미등록 문구가 기준 횟수 이상 반복되고, 12자 이상이며, 평가가 90% 이상 일치하면 기본 문구로 추정합니다. 알려진 문구에는 반복 횟수 조건이 적용되지 않습니다.",
    "help.16": "빈도 규칙은 미등록 기본 문구 후보를 찾는 데 도움이 되지만 반복 횟수만으로 공식 문구라고 단정할 수 없습니다.",
    "help.17": "기준값을 낮추면 미등록 문구를 더 잘 찾지만 플레이어의 반복 표현을 잘못 분류할 위험도 커집니다. 알려진 문구의 일치 검사에는 영향이 없습니다.",
    "help.18": "높이면 보수적: 대규모 반복만 인정하고, 놓친 템플릿은 일반 댓글로 집계됩니다.",
    "help.19": "변경하면 즉시 다시 계산됩니다. 데이터를 다시 받을 필요는 없습니다.",
    "help.20": "메모",
    "help.21": "댓글 카드 오른쪽 위의 ☆를 누르면 \"메모\" 탭에 저장됩니다. 자신만의 메모를 붙일 수 있고, \"댓글로 이동\"을 누르면 목록으로 돌아가 해당 항목을 강조합니다. 메모에는 댓글 스냅숏도 함께 저장되어 원본이 삭제되어도 내용은 남습니다.",
    "help.22": "동기화 속도",
    "help.23": "최신 동기화: 증분, 새 댓글만. 보통 1~2초.",
    "help.24": "전체 수집은 댓글 번호로 나눈 최대 6개 작업과 인기순 작업을 동시에 실행합니다. 소요 시간과 수집률은 네트워크, 댓글 수, API 응답에 따라 달라지며 일정 시간이나 100% 수집을 보장하지 않습니다.",
    "help.25": "대댓글(댓글 아래 답글)",
    "help.26": "댓글 아래 답글도 함께 받아 표시하지만 불완전할 수 있습니다. 원인은 API 자체입니다:",
    "help.27": "시간순 정렬은 일부 댓글을 누락할 수 있으며 API 응답마다 답글 수가 다를 수 있습니다.",
    "help.28": "인기순으로 누락 댓글 일부를 보충할 수 있지만 답글은 미리보기만 반환될 수 있습니다.",
    "help.29": "전용 sub_replies 엔드포인트도 시도했습니다. 파라미터는 검증을 통과하지만(\"잘못된 파라미터\" 오류는 사라짐) 서버는 항상 fatal error를 돌려줍니다. 로그인 상태가 필요하거나, 아직 찾지 못한 필드가 하나 더 필요할 수 있습니다.",
    "help.30": "동일한 댓글이 다른 정렬로 반환되면 필드를 갱신하고 더 많은 답글이 포함된 데이터를 유지합니다. API가 반환하지 않는 답글은 누락될 수 있습니다.",
    "help.31": "기간 필터",
    "help.32": "시작일과 종료일은 하루 전체를 포함하며 한쪽만 지정할 수 있습니다. 요약에는 일치 개수와 기간이 표시됩니다. 지우기는 날짜 조건만 없애며 검색어와 평가 필터는 유지합니다.",
    "help.33": "페이지를 닫으면 어떻게 되나요",
    "help.34": "기본 실행기는 콘솔을 숨깁니다. 자동 종료가 켜져 있으면 페이지를 정상적으로 닫은 약 3초 후 백그라운드 서비스가 종료됩니다. 비정상 종료는 하트비트 시간 초과로 처리합니다. 관리 화면에서 상주 모드를 바꿀 수 있습니다.",
    "app.title": "천성기역 댓글 수집기",
    "tpl.explain": "알려진 기본 문구와 자주 반복되는 문장을 모아 표시합니다. 빈도 기반 분류는 추정입니다. 기준값을 낮추면 더 많이 찾지만 오분류가 늘고, 높이면 놓칠 수 있습니다. 플레이어가 글을 추가한 기본 문구는 직접 작성으로 분류합니다.",
    "add.hint1": "miyoushe에는 공개 레벨 검색 API가 없어서 우회합니다: 게시글 검색 → 본문에서 다른 사람이 붙인 공유 링크 추출 → 실제 이름으로 변환. 그래서 누군가 공유 링크를 올린 레벨만 찾을 수 있고, 못 찾았다고 레벨이 없는 것은 아닙니다 — 아래 방법 2를 쓰세요.",
    "add.hint2": "레벨 ID 찾는 법: 레벨 페이지를 열고 주소창의 level_id=(웹) 또는 id=(게임 내 공유 링크) 뒤 숫자가 그것입니다. 그 숫자만 위 칸에 붙여도 조회됩니다. 링크 전체가 아니어도 됩니다.",
    "add.hint3": "HoYoLAB 전체 링크를 붙여 넣거나 올바른 서버를 선택한 뒤 ID를 입력하세요. 중국 및 글로벌 서버 모두 직접 연결을 먼저 시도하고 실패하면 시스템 프록시, config/proxy.txt, 로컬 프록시 포트를 찾습니다. 프록시 노드는 제공하지 않습니다. 글로벌 화면에서는 ID나 링크로 조회합니다.",
    "btn.gotIt": "확인",
