    "onboard.os": "현재 언어에서는 글로벌 서버 추가 화면이 기본으로 열립니다. 레벨 추가에서 아시아, 유럽, 아메리카 또는 대만/홍콩/마카오를 선택하고 레벨 ID나 HoYoLAB 공유 링크로 조회하세요. 중국 서버로 직접 전환할 수도 있습니다.",
