    "data.dataDir": "Carpeta de datos: ",
    "data.port": "Puerto: {port} (solo local)",
    "data.para": "Copia la carpeta entera para reutilizarla (requiere Node.js). Para entregar la herramienta sin tus datos, usa «Borrar datos» o elimina la carpeta data.",
    "unit.listSep": ", ",
    "grp.current": " (actual)",
    "tpl.unclassified": "{src} (sin clasificar)",
    "help.1": "Valoración: positiva / negativa",
    "help.2": "Se usa directamente el campo is_recommend: es el voto positivo/negativo del propio juego, no una suposición. Maravillas solo tiene positiva y negativa, no hay neutra.",
    "help.3": "is_recommend=true indica una valoración positiva; false, negativa. El porcentaje oficial procede de la API del nivel. Si falta, se muestra el local; pueden abarcar conjuntos distintos.",
    "help.4": "¿Qué son los comentarios por defecto?",
    "help.5": "Si un jugador envía una valoración positiva o negativa sin texto, el juego puede publicar una frase predefinida. Por eso se repiten comentarios como estos:",
    "help.6": "非常优秀的奇域，推荐大家游玩~ (zh · positiva)　奇域仍有待打磨，期待作者的更新~ (zh · negativa)",
    "help.7": "El texto predefinido no aporta detalles propios, pero la valoración puede reflejar una elección real. Oculta las plantillas para centrarte en opiniones concretas; sus valoraciones no son automáticamente inválidas.",
    "help.8": "Se incluyen plantillas conocidas en varios idiomas, entre ellos chino simplificado y tradicional. Estos son algunos ejemplos originales:",
    "help.9": "An outstanding Wonderland! Highly recommended for everyone to try~ (en)　Потрясающий предел! Настоятельно рекомендуем всем! (ru)　とても素晴らしい幻境ですので、皆さんにもオススメです～ (ja)",
    "help.10": "Las frases nuevas o modificadas se clasifican mediante frecuencia y otras condiciones. La detección es aproximada y puede equivocarse; revisa el original cuando sea necesario.",
    "help.11": "¿Para qué sirve «Ocultar plantillas»?",
    "help.12": "Oculta los comentarios clasificados como plantillas puras y conserva el texto añadido. La clasificación automática puede equivocarse.",
    "help.13": "Desactiva ocultar plantillas para filtrar cada categoría por separado: Plantillas positivas / Plantillas negativas / Solo texto propio",
    "help.14": "¿Qué es el «umbral de plantilla»?",
    "help.15": "El umbral predeterminado es 8. Tras quitar algunos signos y espacios, un texto desconocido se considera una posible plantilla si alcanza ese número de repeticiones, tiene al menos 12 caracteres y sus valoraciones coinciden al menos en un 90 %. Las plantillas conocidas no necesitan esta frecuencia.",
    "help.16": "La frecuencia ayuda a encontrar posibles plantillas no registradas, pero la repetición no demuestra su origen oficial.",
    "help.17": "Bajar el umbral hace más sensible la detección de textos desconocidos y aumenta los falsos positivos. No afecta a las plantillas conocidas.",
    "help.18": "Más alto es más conservador: solo cuenta la repetición masiva, y las plantillas no detectadas se cuentan como comentarios normales.",
    "help.19": "Se recalcula al instante al cambiarlo; no hace falta volver a recopilar.",
    "help.20": "Notas",
    "help.21": "Pulsa ☆ arriba a la derecha de una tarjeta para guardarla en la pestaña Notas. Puedes añadir tu propia observación; «Ir al comentario» vuelve a la lista y lo resalta. La nota guarda también una copia del comentario: aunque el original se borre, el texto sigue ahí.",
    "help.22": "¿Qué tan rápida es la sincronización?",
    "help.23": "Sincronizar: incremental, solo lo nuevo. Normalmente 1–2 segundos.",
    "help.24": "La recopilación completa ejecuta hasta seis fragmentos por número de comentario y uno por popularidad en paralelo. La duración y la cobertura dependen de la red y la API; no se garantiza un tiempo fijo ni el 100 %.",
    "help.25": "Respuestas dentro de los comentarios",
    "help.26": "Las respuestas bajo cada comentario también se recogen y se muestran, pero pueden estar incompletas. La causa es la propia API:",
    "help.27": "El orden cronológico puede omitir comentarios y el número de respuestas puede variar entre las respuestas de la API.",
    "help.28": "El orden por popularidad puede recuperar algunos comentarios omitidos, pero las respuestas pueden ser solo vistas previas.",
    "help.29": "Probé el endpoint específico de sub_replies: los parámetros pasan la validación (ya no da «parámetro no válido»), pero el servidor siempre devuelve fatal error; puede que exija sesión iniciada o que falte un campo que no se puede descubrir.",
    "help.30": "Cuando un comentario aparece en distintos órdenes, se actualizan sus campos y se conservan las respuestas más completas recibidas. Pueden faltar respuestas que la API no devuelva.",
    "help.31": "Filtro por rango de fechas",
    "help.32": "Las fechas incluyen el día completo y puedes dejar un extremo vacío. El resumen muestra coincidencias e intervalo. Limpiar solo borra las fechas; conserva palabras clave y filtros de valoración.",
    "help.33": "¿Qué pasa si cierro la página?",
    "help.34": "El iniciador predeterminado oculta la consola. Con salida automática, el servicio se detiene unos tres segundos después de cerrar la página normalmente; el tiempo de espera del latido cubre cierres anómalos. El modo permanente se cambia en Gestión.",
    "app.title": "Recopilador de comentarios",
    "tpl.explain": "Aquí se agrupan plantillas conocidas y textos frecuentes. La detección por frecuencia es aproximada: un umbral bajo detecta más, pero aumenta los falsos positivos; uno alto puede omitir plantillas. El texto añadido por el jugador se considera texto propio.",
    "add.hint1": "miyoushe no ofrece una API pública de búsqueda de niveles, así que se rodea el problema: buscar publicaciones → extraer de su texto los enlaces compartidos → resolverlos al nombre real. Solo se encuentran niveles para los que alguien haya compartido un enlace; no encontrarlo no significa que no exista: usa la opción 2 de abajo.",
    "add.hint2": "Cómo encontrar el ID del nivel: abre la página del nivel y mira la barra de direcciones; el número tras level_id= (web) o id= (enlace compartido del juego) es el ID. Puedes pegar solo ese número en la caja de arriba; no hace falta el enlace completo.",
    "add.hint3": "Pega un enlace completo de HoYoLAB o elige la región correcta antes de introducir el ID. CN y Global prueban primero la conexión directa; si falla, buscan el proxy del sistema, config/proxy.txt y puertos locales. La herramienta no proporciona nodos proxy. La pestaña Global usa ID o enlaces.",
    "btn.gotIt": "Entendido",
    "status.stayOn": "Cambiado a: se cierra con la página",
    "status.stayOff": "Modo permanente en segundo plano activado; vuelve a la salida automática en Gestión.",
