    "onboard.intro": "¡Bienvenido! El idioma se aplica de inmediato. Puedes cambiarlo arriba a la derecha. Esta opción no traduce los comentarios originales.",
    "onboard.cn": "El chino simplificado abre el formulario de China. Selecciona el servidor y consulta un ID de nivel o enlace compartido.",
    "onboard.os": "Este idioma abre por defecto el formulario global. Añade un nivel, selecciona Asia, Europa, América o Taiwán/Hong Kong/Macao y consulta su ID o enlace de HoYoLAB. También puedes cambiar a China manualmente.",
    "onboard.sync": "Tras la consulta, confirma el grupo y añade el nivel con sincronización. Después sincroniza lo nuevo o realiza una actualización completa. Si falla la conexión directa, se avisa y se prueban los proxies locales existentes. Guarda notas con la estrella.",
