    "batch.keepOpen": "Mantener esta ventana abierta al importar",
    "onboard.realIntro": "Elige un idioma. Importaremos comentarios reales de un nivel, probaremos filtros y guardaremos un comentario con una nota. Los datos se guardan localmente. Puedes continuar más tarde.",
    "onboard.importHelp": "Selecciona la región, pega tu ID o enlace y consulta el nivel antes de añadirlo y sincronizar. El chino simplificado abre China por defecto; los demás idiomas, los servidores globales. Puedes cambiarlo. La consulta empieza al dejar de escribir un momento; también puedes pulsar el botón o Intro.",
