    "data.port": "Port : {port} (local uniquement)",
    "data.para": "Copiez tout le dossier pour le réutiliser (Node.js requis). Pour transmettre l’outil sans vos données, utilisez « Supprimer les données » ou effacez le dossier data.",
    "unit.listSep": ", ",
    "grp.current": " (actuel)",
    "tpl.unclassified": "{src} (non classé)",
    "help.1": "Note : positif / négatif",
    "help.2": "On utilise directement le champ is_recommend : c’est le vote positif/négatif du jeu lui-même, pas une estimation. Merveilles ne propose que positif et négatif, pas de neutre.",
    "help.3": "is_recommend=true signifie positif ; false signifie négatif. Le pourcentage officiel vient de l’API du niveau. À défaut, le pourcentage local est affiché ; les ensembles comptés peuvent différer.",
    "help.4": "Que sont les commentaires par défaut ?",
    "help.5": "Lorsqu’un joueur envoie un avis positif ou négatif sans texte, le jeu peut publier une phrase prédéfinie. Cela produit des commentaires répétés comme ceux-ci :",
    "help.6": "非常优秀的奇域，推荐大家游玩~ (zh · positif)　奇域仍有待打磨，期待作者的更新~ (zh · négatif)",
    "help.7": "Le texte prédéfini ne contient pas de détails personnels, mais l’avis peut refléter un choix réel. Masquez les modèles pour lire des retours précis ; leurs évaluations ne sont pas automatiquement invalides.",
    "help.8": "Des modèles connus sont inclus pour plusieurs langues, dont le chinois simplifié et traditionnel. Voici quelques exemples originaux :",
    "help.9": "An outstanding Wonderland! Highly recommended for everyone to try~ (en)　Потрясающий предел! Настоятельно рекомендуем всем! (ru)　とても素晴らしい幻境ですので、皆さんにもオススメです～ (ja)",
    "help.10": "Les textes inconnus ou modifiés sont classés selon leur fréquence et d’autres critères. Cette détection peut se tromper ; vérifiez le texte original si nécessaire.",
    "help.11": "À quoi sert « Masquer les modèles » ?",
    "help.12": "Masque les commentaires classés comme modèles purs et conserve les ajouts du joueur. La classification automatique peut se tromper.",
    "help.13": "Désactivez le masquage des modèles pour filtrer chaque catégorie : Modèles positifs / Modèles négatifs / Texte personnel uniquement",
    "help.14": "À quoi sert le « seuil de modèle » ?",
    "help.15": "Le seuil par défaut est 8. Après retrait de certains signes et espaces, un texte inconnu est considéré comme un modèle probable s’il atteint ce nombre de répétitions, compte au moins 12 caractères et présente au moins 90 % d’avis concordants. Les modèles connus ne sont pas soumis à ce seuil.",
    "help.16": "La fréquence aide à repérer des modèles possibles non répertoriés, mais la répétition ne prouve pas une origine officielle.",
    "help.17": "Abaisser le seuil rend la détection des textes inconnus plus sensible, avec davantage de faux positifs. Les modèles connus ne sont pas concernés.",
    "help.18": "Plus haut = plus prudent : seules les répétitions massives comptent, et les modèles manqués sont comptés comme commentaires ordinaires.",
    "help.19": "Recalcul immédiat après modification, sans nouvelle collecte.",
    "help.20": "Notes",
    "help.21": "Cliquez sur ☆ en haut à droite d’une carte pour l’enregistrer dans l’onglet Notes. Vous pouvez ajouter votre propre remarque ; « Aller au commentaire » revient à la liste et le met en évidence. La note conserve aussi une copie du commentaire : même si l’original est supprimé, le texte reste.",
    "help.22": "La synchronisation est-elle rapide ?",
    "help.23": "Synchroniser : incrémental, seulement les nouveaux. Généralement 1–2 secondes.",
    "help.24": "La collecte complète lance en parallèle jusqu’à six segments par numéro de commentaire et un flux par popularité. La durée et la couverture dépendent du réseau et de l’API ; aucun délai fixe ni couverture de 100 % ne sont garantis.",
    "help.25": "Réponses sous les commentaires",
    "help.26": "Les réponses sous les commentaires sont aussi récupérées et affichées, mais peuvent être incomplètes. La cause vient de l’API :",
    "help.27": "Le tri chronologique peut omettre certains commentaires et le nombre de réponses renvoyées peut varier selon les réponses de l’API.",
    "help.28": "Le tri par popularité peut retrouver certains commentaires omis, mais ne renvoie parfois qu’un aperçu des réponses.",
    "help.29": "J’ai essayé l’endpoint dédié sub_replies : les paramètres passent la validation (plus d’« invalid parameter »), mais le serveur renvoie toujours fatal error — il exige peut-être une session connectée, ou un champ supplémentaire introuvable.",
    "help.30": "Lorsqu’un commentaire est renvoyé dans plusieurs tris, ses champs sont actualisés et les réponses les plus complètes sont conservées. Les réponses omises par l’API peuvent manquer.",
    "help.31": "Filtre par période",
    "help.32": "Les dates incluent la journée entière ; une seule limite suffit. Le résumé affiche le nombre de résultats et la période. Effacer supprime uniquement les dates et conserve mots-clés et filtres d’évaluation.",
    "help.33": "Que se passe-t-il si je ferme la page ?",
    "help.34": "Le lanceur par défaut masque la console. Avec l’arrêt automatique, le service s’arrête environ trois secondes après une fermeture normale de la page ; un délai de surveillance couvre les fermetures anormales. Le mode permanent se règle dans Gestion.",
    "app.title": "Collecteur de commentaires",
    "tpl.explain": "Les modèles connus et les textes fréquents sont regroupés ici. La détection par fréquence est une estimation : un seuil bas détecte davantage mais peut se tromper ; un seuil haut peut manquer des modèles. Les ajouts du joueur restent du texte personnel.",
    "add.hint1": "miyoushe n’expose pas d’API publique de recherche de niveaux : on contourne en cherchant des publications → en extrayant les liens de partage présents dans leur texte → puis en les résolvant en vrais noms. Seuls les niveaux pour lesquels quelqu’un a partagé un lien sont trouvables ; ne rien trouver ne prouve pas que le niveau n’existe pas : utilisez l’option 2 ci-dessous.",
    "add.hint2": "Comment trouver l’ID du niveau : ouvrez la page du niveau et regardez la barre d’adresse ; le nombre après level_id= (web) ou id= (lien de partage en jeu) est l’ID. Vous pouvez coller uniquement ce nombre dans le champ ci-dessus ; le lien complet n’est pas nécessaire.",
    "add.hint3": "Collez un lien HoYoLAB complet ou choisissez la bonne région avant de saisir l’ID. CN et Global essaient d’abord un accès direct puis, en cas d’échec, les proxys système, config/proxy.txt et les ports locaux. L’outil ne fournit aucun nœud proxy. L’onglet Global utilise un ID ou un lien.",
    "btn.gotIt": "Compris",
