    "onboard.sync": "Après la recherche, confirmez le groupe et ajoutez le niveau avec synchronisation. Synchronisez ensuite les nouveautés ou actualisez toute la collection. Si la connexion directe échoue, un message apparaît et les proxys locaux existants sont essayés. Utilisez les étoiles pour enregistrer des notes.",
