    "batch.keepOpen": "Garder cette fenêtre ouverte après l’import",
    "onboard.realIntro": "Choisissez une langue. Nous allons importer de vrais commentaires, essayer les filtres, enregistrer un commentaire et rédiger une note. Les données seront conservées localement. Vous pouvez reprendre plus tard.",
    "onboard.importHelp": "Choisissez la région, collez votre identifiant ou lien puis recherchez le niveau avant de l’ajouter et de synchroniser. Le chinois simplifié utilise la Chine par défaut, les autres langues les serveurs internationaux. Vous pouvez changer. La recherche démarre après une courte pause de saisie ; le bouton ou Entrée fonctionnent aussi.",
