    "data.dataDir": "Thư mục dữ liệu: ",
    "data.port": "Cổng: {port} (chỉ máy này)",
    "data.para": "Sao chép cả thư mục để dùng ở nơi khác (cần Node.js). Muốn chuyển giao mà không kèm dữ liệu bình luận, dùng \"Xoá dữ liệu\" ở trên hoặc xoá thư mục data.",
    "unit.listSep": ", ",
    "grp.current": " (hiện tại)",
    "tpl.unclassified": "{src} (chưa phân loại)",
    "help.1": "Đánh giá: tích cực / tiêu cực",
    "help.2": "Dùng thẳng trường is_recommend — đó chính là lượt thích/không thích của game, không phải phỏng đoán. Wonderland chỉ có tích cực và tiêu cực, không có trung lập.",
    "help.3": "is_recommend=true là tích cực, false là tiêu cực. Tỷ lệ chính thức lấy từ API màn chơi. Nếu không có sẽ hiện tỷ lệ cục bộ; phạm vi thống kê có thể khác nhau.",
    "help.4": "Bình luận mặc định là gì",
    "help.5": "Nếu người chơi chỉ gửi đánh giá tích cực hoặc tiêu cực mà không viết nội dung, trò chơi có thể đăng câu có sẵn. Vì vậy xuất hiện các bình luận lặp lại như:",
    "help.6": "非常优秀的奇域，推荐大家游玩~ (zh · tích cực)　奇域仍有待打磨，期待作者的更新~ (zh · tiêu cực)",
    "help.7": "Câu có sẵn không chứa góp ý chi tiết do người chơi viết, nhưng đánh giá vẫn có thể phản ánh lựa chọn thật. Ẩn mẫu giúp tập trung vào ý kiến cụ thể; không có nghĩa các đánh giá đó vô hiệu.",
    "help.8": "Đã tích hợp các mẫu đã biết bằng nhiều ngôn ngữ, gồm tiếng Trung giản thể và phồn thể. Sau đây là một số ví dụ nguyên văn:",
    "help.9": "An outstanding Wonderland! Highly recommended for everyone to try~ (en)　Потрясающий предел! Настоятельно рекомендуем всем! (ru)　とても素晴らしい幻境ですので、皆さんにもオススメです～ (ja)",
    "help.10": "Câu chưa có trong danh sách hoặc đã thay đổi được suy đoán bằng tần suất và điều kiện khác. Có thể phân loại sai; hãy kiểm tra nguyên văn khi cần.",
    "help.11": "\"Ẩn văn bản mẫu\" để làm gì",
    "help.12": "Ẩn bình luận được phân loại là mẫu thuần túy và giữ phần người chơi viết thêm. Phân loại tự động có thể sai.",
    "help.13": "Tắt ẩn mẫu để lọc riêng từng loại: Mẫu tích cực / Mẫu tiêu cực / Chỉ nội dung tự viết",
    "help.14": "\"Ngưỡng mẫu\" là gì",
    "help.15": "Ngưỡng mặc định là 8. Sau khi bỏ một số dấu câu và khoảng trắng, câu chưa biết được coi là mẫu có khả năng cao nếu lặp đạt ngưỡng, dài ít nhất 12 ký tự và ít nhất 90% đánh giá giống nhau. Mẫu đã biết không chịu ngưỡng tần suất này.",
    "help.16": "Tần suất giúp tìm mẫu có khả năng chưa được ghi nhận, nhưng sự lặp lại không chứng minh nguồn gốc chính thức.",
    "help.17": "Giảm ngưỡng làm nhận diện nội dung lạ nhạy hơn và dễ nhận nhầm câu người chơi lặp lại. Không ảnh hưởng đến khớp mẫu đã biết.",
    "help.18": "Đặt cao thì thận trọng hơn: chỉ tính lặp lại quy mô lớn, mẫu bị bỏ sót sẽ được tính là bình luận thường.",
    "help.19": "Đổi xong tính lại ngay, không cần lấy dữ liệu lại.",
    "help.20": "Ghi chú",
    "help.21": "Nhấn ☆ ở góc trên bên phải thẻ bình luận để lưu vào tab \"Ghi chú\". Có thể kèm ghi chú riêng; \"Tới bình luận\" sẽ quay lại danh sách và tô sáng dòng đó. Ghi chú lưu kèm bản sao bình luận — kể cả khi bình luận gốc bị xoá, nội dung vẫn còn.",
    "help.22": "Đồng bộ nhanh không",
    "help.23": "Đồng bộ mới: tăng dần, chỉ lấy cái mới. Thường 1–2 giây.",
    "help.24": "Thu thập toàn bộ chạy song song tối đa sáu luồng theo số bình luận và một luồng theo độ phổ biến. Thời gian và độ đầy đủ phụ thuộc mạng và API; không bảo đảm thời gian cố định hay đủ 100%.",
    "help.25": "Trả lời dưới bình luận",
    "help.26": "Các trả lời dưới bình luận cũng được lấy về và hiển thị, nhưng có thể không đầy đủ. Nguyên nhân nằm ở API:",
    "help.27": "Sắp xếp theo thời gian có thể bỏ sót bình luận, và số trả lời có thể khác nhau giữa các phản hồi API.",
    "help.28": "Sắp xếp theo độ phổ biến có thể bổ sung một số bình luận thiếu, nhưng trả lời có thể chỉ là bản xem trước.",
    "help.29": "Tôi đã thử endpoint sub_replies riêng: tham số qua được kiểm tra (không còn báo \"tham số không hợp lệ\"), nhưng máy chủ luôn trả fatal error — có thể cần trạng thái đăng nhập, hoặc thiếu một trường không thể tìm ra.",
    "help.30": "Khi một bình luận xuất hiện ở nhiều thứ tự, các trường được cập nhật và giữ bộ trả lời đầy đủ hơn. Những trả lời API không gửi về vẫn có thể thiếu.",
    "help.31": "Lọc theo khoảng thời gian",
    "help.32": "Ngày đầu và cuối đều tính trọn ngày; có thể chỉ đặt một đầu. Tóm tắt hiện số khớp và khoảng thời gian. Xóa chỉ xóa ngày, giữ nguyên từ khóa và bộ lọc đánh giá.",
    "help.33": "Đóng trang thì sao",
    "help.34": "Trình khởi động mặc định ẩn cửa sổ dòng lệnh. Khi bật tự thoát, dịch vụ nền dừng khoảng ba giây sau khi đóng trang bình thường; đóng bất thường được xử lý bằng hết thời gian kiểm tra kết nối. Có thể đổi chế độ chạy liên tục ở trang Quản lý.",
    "app.title": "Trình thu thập bình luận",
    "tpl.explain": "Nơi đây nhóm mẫu đã biết và câu lặp thường xuyên. Nhận diện bằng tần suất là suy đoán: ngưỡng thấp nhạy hơn nhưng dễ nhận nhầm; ngưỡng cao có thể bỏ sót. Phần người chơi viết thêm được coi là nội dung tự viết.",
    "add.hint1": "miyoushe không có API tìm kiếm màn chơi công khai, nên phải đi đường vòng: tìm bài đăng → lấy liên kết chia sẻ mà người khác dán trong nội dung → đổi thành tên thật. Vì vậy chỉ tìm được màn chơi mà ai đó đã từng chia sẻ liên kết; không tìm thấy không có nghĩa là màn chơi không tồn tại — hãy dùng cách 2 bên dưới.",
    "add.hint2": "Cách tìm ID màn chơi: mở trang màn chơi và xem thanh địa chỉ — dãy số sau level_id= (bản web) hoặc id= (liên kết chia sẻ trong game) chính là ID. Bạn có thể dán riêng dãy số đó vào ô trên, không cần cả liên kết.",
    "add.hint3": "Dán liên kết HoYoLAB đầy đủ hoặc chọn đúng khu vực trước khi nhập ID. Cả máy chủ Trung Quốc và quốc tế đều thử kết nối trực tiếp, rồi tìm proxy hệ thống, config/proxy.txt và cổng cục bộ nếu thất bại. Công cụ không cung cấp proxy. Trang quốc tế dùng ID hoặc liên kết.",
