    "batch.mismatch": "Khu vực trong liên kết không khớp dòng này. Hãy chuyển sang dòng đúng.",
    "batch.saved": "Đã nhập: {name}",
    "batch.summary": "Đã nhập {ok} khu vực; lỗi {failed}. Các dòng thành công sẽ không gửi lại.",
    "batch.syncFailed": "Đã lưu đăng ký nhưng đồng bộ chưa thành công hoàn toàn. Xem nhật ký hoặc cập nhật sau.",
    "batch.include": "Bao gồm",
    "lookup.invalid": "Định dạng không hợp lệ. Nhập ID dạng số hoặc liên kết có level_id / id.",
    "lookup.notFound": "Dịch vụ chính thức báo màn chơi không tồn tại. Kiểm tra ID và khu vực; đây không phải lỗi kết nối proxy.",
    "lookup.business": "Dịch vụ chính thức từ chối truy vấn. Kiểm tra khu vực và quyền truy cập hoặc thử lại sau.",
    "lookup.proxyMissing": "Kết nối trực tiếp thất bại và không tìm thấy proxy cục bộ dùng được. Bật proxy rồi thử lại. ID chưa được xác minh.",
    "lookup.proxyFailed": "Truy cập proxy thất bại hoặc bị chặn, không có đường kết nối dùng được. Kiểm tra nút proxy. ID chưa được xác minh.",
    "lookup.network": "Yêu cầu mạng chưa hoàn tất. Màn chơi chưa được xác minh; kiểm tra kết nối rồi thử lại.",
    "batch.keepOpen": "Giữ cửa sổ này mở sau khi nhập",
    "onboard.realIntro": "Chọn ngôn ngữ. Chúng ta sẽ nhập bình luận thật, thử bộ lọc, lưu bình luận và viết ghi chú. Dữ liệu được lưu cục bộ. Bạn có thể tiếp tục sau.",
    "onboard.importHelp": "Chọn khu vực, dán ID hoặc liên kết của bạn và tra cứu để xác nhận trước khi thêm và đồng bộ. Tiếng Trung giản thể mặc định máy chủ Trung Quốc, các ngôn ngữ khác mặc định quốc tế. Bạn có thể đổi. Tra cứu tự động bắt đầu sau khi bạn ngừng gõ một lát; cũng có thể bấm nút hoặc Enter.",
    "onboard.syncWait": "Đang tải bình luận. Theo dõi nhật ký trên trang chính. Hướng dẫn tiếp tục sau khi xác nhận đã lưu.",
    "onboard.syncRetry": "Lần đồng bộ đầu chưa thành công. Kiểm tra nhật ký, mạng hoặc proxy rồi thử lại. Đăng ký màn chơi được giữ lại.",
    "onboard.empty": "Đồng bộ xong nhưng không có bình luận khả dụng. Chọn màn chơi có bình luận hoặc thử lại sau. Hướng dẫn chưa hoàn tất.",
    "onboard.labelsTitle": "Nhãn và bộ lọc",
    "onboard.labelsBody": "Nhãn tích cực và tiêu cực theo đánh giá chính thức. Mẫu được công cụ nhận dạng và có thể sai. Bấm bộ lọc hoặc ẩn mẫu, quan sát danh sách rồi tiếp tục.",
    "onboard.saveTitle": "Lưu một bình luận",
    "onboard.saveBody": "Bấm ☆ trên bình luận để lưu bản chụp vào ghi chú. Sau đó bấm Tiếp theo để kiểm tra việc lưu.",
    "onboard.needStar": "Chưa xác nhận được việc lưu. Bấm ☆, chờ lưu xong rồi bấm Tiếp theo lại.",
    "onboard.editTitle": "Viết ghi chú của bạn",
    "onboard.editBody": "Đã mở bình luận vừa lưu. Viết ghi chú vào thẻ được đánh dấu, chờ tự động lưu rồi bấm Tiếp theo. Hướng dẫn sẽ kiểm tra bản ghi cục bộ.",
    "onboard.waitSave": "Viết ghi chú không rỗng và chờ tự động lưu xong.",
    "onboard.doneTitle": "Hoàn tất thực hành đầu tiên",
    "onboard.doneBody": "Đã xác nhận dữ liệu được lưu cục bộ. Bình luận dùng để đồng bộ và lọc; Ghi chú nhóm nhiều màn chơi, tìm bản gốc và xuất; Quản lý chỉnh nhóm, đường dẫn và chế độ chạy thường trực.",
    "error.entryMissing": "Màn chơi đã bị gỡ. Hãy làm mới danh sách.",
    "error.noteMissing": "Ghi chú đã bị gỡ. Hãy lưu lại bình luận.",
    "error.noteSave": "Thao tác ghi chú thất bại",
    "error.syncBusy": "Đang đồng bộ. Hãy chờ trước khi gỡ, xóa hoặc thêm mục.",
    "error.storage": "Không thể đọc hoặc lưu dữ liệu cục bộ. Kiểm tra tệp và quyền thư mục.",
    "error.request": "Yêu cầu thất bại. Kiểm tra dịch vụ cục bộ hoặc mạng.",
    "error.jobChanged": "Cửa sổ khác đã thay đổi tác vụ đồng bộ. Làm mới rồi thử lại.",
    "onboard.translationTip": "Bạn có thể dùng tính năng dịch của Chrome hoặc trình duyệt khác, hay tiện ích dịch, để đọc bình luận bằng ngôn ngữ quen thuộc và tổng hợp phản hồi hữu ích."
