    "data.port": "Port: {port} (nur lokal)",
    "data.para": "Kopiere den ganzen Ordner zur weiteren Nutzung (Node.js nötig). Um das Tool ohne deine Daten weiterzugeben, nutze „Daten löschen“ oder lösche den data-Ordner.",
    "unit.listSep": ", ",
    "grp.current": " (aktuell)",
    "tpl.unclassified": "{src} (unbekannt)",
    "help.1": "Bewertung: positiv / negativ",
    "help.2": "Es wird direkt das Feld is_recommend verwendet – das ist die positive/negative Stimme des Spiels selbst, keine Schätzung. Wunderland kennt nur positiv und negativ, kein neutral.",
    "help.3": "is_recommend=true bedeutet positiv, false negativ. Der offizielle Positivanteil stammt aus der Level-API. Fehlt er, wird der lokale Anteil angezeigt; die erfassten Bewertungen können sich unterscheiden.",
    "help.4": "Was sind Standardkommentare?",
    "help.5": "Wenn ein Spieler ohne Text eine positive oder negative Bewertung abgibt, kann das Spiel einen vorgegebenen Text veröffentlichen. So entstehen wiederholte Kommentare wie diese:",
    "help.6": "非常优秀的奇域，推荐大家游玩~ (zh · positiv)　奇域仍有待打磨，期待作者的更新~ (zh · negativ)",
    "help.7": "Vorgegebene Texte enthalten keine eigenen Details, die Bewertung kann aber eine echte Entscheidung ausdrücken. Blende Vorlagen aus, um konkrete Rückmeldungen zu lesen; ihre Bewertungen sind nicht automatisch ungültig.",
    "help.8": "Bekannte Vorlagen für mehrere Sprachen sind enthalten, auch für vereinfachtes und traditionelles Chinesisch. Es folgen Originalbeispiele:",
    "help.9": "An outstanding Wonderland! Highly recommended for everyone to try~ (en)　Потрясающий предел! Настоятельно рекомендуем всем! (ru)　とても素晴らしい幻境ですので、皆さんにもオススメです～ (ja)",
    "help.10": "Unbekannte oder geänderte Texte werden anhand ihrer Häufigkeit und weiterer Bedingungen geschätzt. Fehlzuordnungen sind möglich; prüfe bei Bedarf den Originaltext.",
    "help.11": "Wozu „Vorlagen ausblenden“?",
    "help.12": "Als reine Vorlagen eingestufte Kommentare ausblenden und Ergänzungen des Spielers behalten. Die automatische Zuordnung kann falsch sein.",
    "help.13": "Deaktiviere das Ausblenden von Vorlagen, um Kategorien einzeln zu filtern: Positive Vorlagen / Negative Vorlagen / Nur eigener Text",
    "help.14": "Was ist die „Vorlagenschwelle“?",
    "help.15": "Der Standardschwellenwert ist 8. Nach Entfernung einiger Satz- und Leerzeichen gilt unbekannter Text als mögliche Vorlage, wenn er mindestens so oft vorkommt, mindestens 12 Zeichen lang ist und mindestens 90 % der Bewertungen übereinstimmen. Bekannte Vorlagen benötigen diese Häufigkeit nicht.",
    "help.16": "Häufigkeit hilft, mögliche neue Vorlagen zu finden. Wiederholung allein belegt jedoch keine offizielle Herkunft.",
    "help.17": "Ein niedrigerer Schwellenwert erkennt unbekannte Texte leichter, führt aber häufiger zu falschen Treffern. Bekannte Vorlagen sind davon unabhängig.",
    "help.18": "Höher ist konservativer: nur massenhafte Wiederholung zählt, übersehene Vorlagen gelten als normale Kommentare.",
    "help.19": "Wird nach der Änderung sofort neu berechnet, kein erneutes Laden nötig.",
    "help.20": "Notizen",
    "help.21": "Klicke ☆ oben rechts auf einer Kommentarkarte, um sie im Tab „Notizen“ zu speichern. Du kannst eine eigene Bemerkung ergänzen; „Zum Kommentar“ springt zurück zur Liste und hebt ihn hervor. Die Notiz speichert auch einen Schnappschuss des Kommentars – selbst wenn das Original gelöscht wird, bleibt der Text erhalten.",
    "help.22": "Wie schnell ist die Synchronisierung?",
    "help.23": "Neueste syncen: inkrementell, nur Neues. Meist 1–2 Sekunden.",
    "help.24": "Die vollständige Sammlung nutzt parallel bis zu sechs Bereiche nach Kommentarnummer und einen Beliebtheitsstrom. Dauer und Vollständigkeit hängen von Netzwerk und API ab; feste Zeiten und 100 % Abdeckung werden nicht garantiert.",
    "help.25": "Antworten unter Kommentaren",
    "help.26": "Antworten unter Kommentaren werden mitgeladen und angezeigt, können aber unvollständig sein. Ursache ist die API selbst:",
    "help.27": "Die zeitliche Sortierung kann Kommentare auslassen. Auch die Anzahl der Antworten kann je nach API-Ergebnis variieren.",
    "help.28": "Die Sortierung nach Beliebtheit kann manche fehlenden Kommentare ergänzen, liefert Antworten aber unter Umständen nur als Vorschau.",
    "help.29": "Ich habe den eigenen sub_replies-Endpunkt probiert: Die Parameter bestehen die Prüfung (kein „invalid parameter“ mehr), aber der Server antwortet immer mit fatal error – vielleicht ist eine Anmeldung nötig oder ein weiteres, nicht auffindbares Feld.",
    "help.30": "Wird derselbe Kommentar in mehreren Sortierungen geliefert, werden seine Felder aktualisiert und die vollständigeren Antworten behalten. Von der API ausgelassene Antworten können weiterhin fehlen.",
    "help.31": "Zeitraumfilter",
    "help.32": "Beide Datumsgrenzen schließen den ganzen Tag ein; eine Grenze kann leer bleiben. Die Übersicht zeigt Trefferzahl und Zeitraum. Leeren entfernt nur die Datumsbedingungen; Suchtext und Bewertungsfilter bleiben.",
    "help.33": "Was passiert beim Schließen der Seite?",
    "help.34": "Der Standardstarter verbirgt die Konsole. Bei automatischem Beenden stoppt der Hintergrunddienst etwa drei Sekunden nach normalem Schließen der Seite. Bei unerwartetem Schließen greift die Zeitüberschreitung der Verbindungskontrolle. Dauerbetrieb lässt sich unter Verwalten ändern.",
    "app.title": "Kommentar-Sammler",
    "tpl.explain": "Hier werden bekannte Vorlagen und häufige Texte gruppiert. Die Häufigkeitserkennung ist eine Schätzung: niedrige Schwellen finden mehr, können aber irren; hohe können Vorlagen übersehen. Ergänzungen des Spielers zählen als eigener Text.",
    "add.hint1": "miyoushe bietet keine öffentliche Level-Suche, deshalb der Umweg: Beiträge durchsuchen → geteilte Links aus dem Beitragstext ziehen → zu echten Namen auflösen. Gefunden werden nur Level, für die jemand einen Link geteilt hat; nichts zu finden heißt nicht, dass es das Level nicht gibt – nutze Weg 2 unten.",
    "add.hint2": "So findest du die Level-ID: Öffne die Levelseite und schau in die Adresszeile – die Zahl nach level_id= (Web) bzw. id= (In-Game-Link) ist die ID. Du kannst nur diese Zahl oben einfügen, der ganze Link ist nicht nötig.",
    "add.hint3": "Füge einen vollständigen HoYoLAB-Link ein oder wähle vor Eingabe der ID die richtige Region. CN und Global versuchen zuerst direkten Zugriff, danach Systemproxy, config/proxy.txt und lokale Proxy-Ports. Das Tool stellt keine Proxy-Knoten bereit. Der Global-Bereich nutzt IDs oder Links.",
    "btn.gotIt": "Verstanden",
