    "onboard.reopen": "Erste Schritte",
    "onboard.language": "Sprache wählen",
    "onboard.intro": "Willkommen! Die gewählte Sprache wird sofort übernommen. Du kannst sie später oben rechts ändern. Originalkommentare werden dadurch nicht übersetzt.",
    "onboard.cn": "Bei vereinfachtem Chinesisch öffnet sich das Formular für China-Server. Wähle den Server und suche nach einer Level-ID oder einem Freigabelink.",
    "onboard.os": "Für diese Sprache öffnet sich standardmäßig das globale Formular. Füge ein Level hinzu, wähle Asien, Europa, Amerika oder Taiwan/Hongkong/Macau und suche nach der ID oder einem HoYoLAB-Link. Du kannst auch manuell zu China-Servern wechseln.",
    "onboard.sync": "Bestätige nach der Suche die Gruppe und füge das Level mit Synchronisierung hinzu. Synchronisiere später neue Kommentare oder lade alles neu, um vorhandene Inhalte zu aktualisieren. Bei fehlgeschlagener Direktverbindung werden Hinweise angezeigt und vorhandene lokale Proxys versucht. Sterne speichern Kommentare als Notizen.",
    "onboard.next": "Weiter",
