    "batch.open": "Mehrere Regionen importieren",
    "batch.hint": "Gib für jede Region die eigene Level-ID oder den Link ein. Nicht veröffentlichte Regionen bleiben leer. Nur ausgefüllte Zeilen werden importiert; fehlgeschlagene lassen sich korrigieren und erneut versuchen.",
    "batch.groupHint": "Der erste gefundene Levelname wird als Gruppe eingetragen. Weitere Namen erscheinen als Vorschläge. Du kannst eine Gruppe wählen oder selbst eingeben; manuelle Änderungen bleiben erhalten. Lösche den eigenen Namen, um den automatischen wiederherzustellen.",
