    "batch.saved": "Importiert: {name}",
    "batch.summary": "{ok} Regionen importiert; {failed} fehlgeschlagen. Erfolgreiche Zeilen werden nicht erneut gesendet.",
    "batch.syncFailed": "Die Registrierung wurde gespeichert, aber die Synchronisierung war nicht vollständig erfolgreich. Prüfe das Protokoll oder aktualisiere später.",
    "batch.include": "Einbeziehen",
    "lookup.invalid": "Ungültiges Format. Gib eine numerische Level-ID oder einen Link mit level_id / id ein.",
    "lookup.notFound": "Der offizielle Dienst meldet, dass das Level nicht existiert. Prüfe ID und Region; dies ist kein Proxy-Verbindungsfehler.",
    "lookup.business": "Der offizielle Dienst hat die Anfrage abgelehnt. Prüfe Region und Zugriffsrechte oder versuche es später.",
    "lookup.proxyMissing": "Direktzugriff fehlgeschlagen, kein nutzbarer lokaler Proxy gefunden. Starte deinen Proxy und versuche es erneut. Die ID ist noch nicht geprüft.",
    "lookup.proxyFailed": "Proxy-Zugriff fehlgeschlagen oder blockiert, kein funktionierender Weg verfügbar. Prüfe den Proxy-Knoten. Die ID ist noch nicht geprüft.",
    "lookup.network": "Die Netzwerkanfrage wurde nicht abgeschlossen. Das Level ist noch nicht geprüft; prüfe die Verbindung und versuche es erneut.",
    "batch.keepOpen": "Dieses Fenster nach dem Import geöffnet lassen",
    "onboard.realIntro": "Wähle eine Sprache. Wir importieren echte Kommentare, probieren Filter aus und speichern einen Kommentar mit eigener Notiz. Die Daten werden lokal gespeichert. Du kannst später fortfahren.",
    "onboard.importHelp": "Wähle die Region, füge deine Level-ID oder einen Link ein und prüfe das Level vor dem Hinzufügen und Synchronisieren. Vereinfachtes Chinesisch startet mit China, andere Sprachen mit globalen Servern. Du kannst wechseln. Nach einer kurzen Eingabepause startet die Suche automatisch; Suchknopf oder Eingabetaste funktionieren ebenfalls.",
    "onboard.syncWait": "Kommentare werden heruntergeladen. Verfolge das Protokoll auf der Hauptseite. Nach der Speicherprüfung geht es weiter.",
    "onboard.syncRetry": "Die erste Synchronisierung ist fehlgeschlagen. Prüfe Protokoll, Netzwerk oder Proxy und versuche es erneut. Die Registrierung bleibt erhalten.",
    "onboard.empty": "Die Synchronisierung endete ohne verfügbare Kommentare. Wähle ein Level mit Kommentaren oder versuche es später erneut. Die Anleitung ist noch nicht abgeschlossen.",
    "onboard.labelsTitle": "Labels und Filter",
    "onboard.labelsBody": "Positive und negative Labels entsprechen offiziellen Bewertungen. Vorlagen werden automatisch erkannt und können falsch zugeordnet sein. Klicke einen Filter an oder blende Vorlagen aus und beobachte die Liste.",
    "onboard.saveTitle": "Kommentar speichern",
    "onboard.saveBody": "Klicke auf ☆ an einem Kommentar, um eine Kopie in den Notizen zu speichern. Klicke danach auf Weiter, damit die Speicherung geprüft wird.",
    "onboard.needStar": "Die Speicherung wurde noch nicht bestätigt. Klicke auf ☆, warte und klicke erneut auf Weiter.",
    "onboard.editTitle": "Eigene Notiz schreiben",
    "onboard.editBody": "Der gespeicherte Kommentar ist geöffnet. Schreibe eine Notiz in die markierte Karte, warte auf das automatische Speichern und klicke auf Weiter. Der lokale Eintrag wird geprüft.",
    "onboard.waitSave": "Schreibe eine nicht leere Notiz und warte auf das automatische Speichern.",
    "onboard.doneTitle": "Erste Übung abgeschlossen",
    "onboard.doneBody": "Die lokale Speicherung ist bestätigt. Kommentare bietet Synchronisierung und Filter; Notizen gruppiert Level, findet Originale und exportiert; Verwaltung steuert Gruppen, Pfade und dauerhaften Betrieb.",
    "error.entryMissing": "Das Level wurde entfernt. Aktualisiere die Liste.",
