    "help.1": "Penilaian: positif / negatif",
    "help.2": "Langsung memakai field is_recommend — itu suara positif/negatif dari game itu sendiri, bukan tebakan. Wonderland hanya punya positif dan negatif, tidak ada netral.",
    "help.3": "is_recommend=true berarti positif, false berarti negatif. Persentase resmi berasal dari API level. Jika tidak ada, persentase lokal ditampilkan; cakupan penilaiannya dapat berbeda.",
    "help.4": "Apa itu komentar bawaan",
    "help.5": "Jika pemain mengirim penilaian positif atau negatif tanpa teks, game dapat memposting kalimat bawaan. Karena itu muncul komentar berulang seperti:",
    "help.6": "非常优秀的奇域，推荐大家游玩~ (zh · positif)　奇域仍有待打磨，期待作者的更新~ (zh · negatif)",
    "help.7": "Kalimat bawaan tidak berisi masukan terperinci, tetapi penilaiannya dapat mencerminkan pilihan nyata pemain. Sembunyikan templat untuk membaca saran khusus; penilaian tersebut tidak otomatis tidak sah.",
    "help.8": "Templat yang dikenal tersedia untuk beberapa bahasa, termasuk bahasa Tionghoa sederhana dan tradisional. Berikut contoh teks aslinya:",
    "help.9": "An outstanding Wonderland! Highly recommended for everyone to try~ (en)　Потрясающий предел! Настоятельно рекомендуем всем! (ru)　とても素晴らしい幻境ですので、皆さんにもオススメです～ (ja)",
    "help.10": "Kalimat baru atau berubah diperkirakan dari frekuensi dan kondisi lain. Klasifikasi dapat salah; periksa teks asli jika diperlukan.",
    "help.11": "Untuk apa \"Sembunyikan templat\"",
    "help.12": "Sembunyikan komentar yang diklasifikasikan sebagai templat murni dan pertahankan tambahan pemain. Klasifikasi otomatis dapat salah.",
    "help.13": "Nonaktifkan sembunyikan templat untuk memfilter setiap kategori: Templat positif / Templat negatif / Hanya teks pemain",
    "help.14": "Apa itu \"ambang templat\"",
    "help.15": "Ambang bawaan adalah 8. Setelah sebagian tanda baca dan spasi dihapus, teks yang belum dikenal dianggap kemungkinan templat jika berulang setidaknya sebanyak ambang, panjangnya minimal 12 karakter, dan minimal 90% penilaiannya sama. Templat yang dikenal tidak memerlukan frekuensi ini.",
    "help.16": "Frekuensi membantu menemukan kandidat templat baru, tetapi pengulangan saja tidak membuktikan sumber resmi.",
    "help.17": "Menurunkan ambang membuat deteksi teks baru lebih sensitif dan menambah risiko salah mengenali kalimat pemain. Pencocokan templat dikenal tidak terpengaruh.",
    "help.18": "Lebih tinggi lebih konservatif: hanya pengulangan besar yang diakui, templat yang terlewat dihitung sebagai komentar biasa.",
    "help.19": "Setelah diubah langsung dihitung ulang, tanpa mengambil data lagi.",
    "help.20": "Catatan",
    "help.21": "Klik ☆ di kanan atas kartu komentar untuk menyimpannya ke tab \"Catatan\". Kamu bisa menambahkan catatan sendiri; \"Ke komentar\" akan kembali ke daftar dan menyorotnya. Catatan juga menyimpan salinan komentar — meski aslinya dihapus, isinya tetap ada.",
    "help.22": "Seberapa cepat sinkronnya",
    "help.23": "Sinkron terbaru: bertahap, hanya yang baru. Biasanya 1–2 detik.",
    "help.24": "Pengambilan penuh menjalankan hingga enam alur berdasarkan nomor komentar dan satu alur popularitas secara paralel. Waktu dan kelengkapan bergantung pada jaringan dan API; durasi tetap maupun cakupan 100% tidak dijamin.",
    "help.25": "Balasan di bawah komentar",
    "help.26": "Balasan di bawah komentar juga diambil dan ditampilkan, tetapi bisa tidak lengkap. Penyebabnya API itu sendiri:",
    "help.27": "Urutan waktu dapat melewatkan sebagian komentar, dan jumlah balasan dapat berbeda di antara respons API.",
    "help.28": "Urutan popularitas dapat melengkapi sebagian komentar yang terlewat, tetapi balasannya mungkin hanya cuplikan.",
    "help.29": "Saya sudah mencoba endpoint sub_replies khusus: parameternya lolos validasi (tidak lagi \"parameter tidak valid\"), tetapi server selalu mengembalikan fatal error — mungkin butuh sesi login, atau masih kurang satu field yang tak bisa ditemukan.",
    "help.30": "Jika komentar yang sama dikembalikan dari urutan berbeda, kolomnya diperbarui dan balasan yang lebih lengkap dipertahankan. Balasan yang tidak dikirim API tetap dapat hilang.",
    "help.31": "Filter rentang tanggal",
    "help.32": "Tanggal awal dan akhir mencakup sehari penuh; satu batas boleh dikosongkan. Ringkasan menampilkan jumlah cocok dan rentang. Bersihkan hanya menghapus tanggal; kata kunci dan filter penilaian tetap.",
    "help.33": "Apa yang terjadi kalau halaman ditutup",
    "help.34": "Peluncur bawaan menyembunyikan konsol. Jika keluar otomatis aktif, layanan latar berhenti sekitar tiga detik setelah halaman ditutup normal; penutupan tidak normal ditangani lewat batas waktu pemeriksaan koneksi. Mode tetap berjalan diubah di Kelola.",
    "app.title": "Pengumpul Komentar",
    "tpl.explain": "Templat dikenal dan kalimat berulang dikelompokkan di sini. Deteksi frekuensi adalah perkiraan: ambang rendah menemukan lebih banyak tetapi dapat salah; ambang tinggi dapat melewatkan templat. Tambahan pemain dihitung sebagai teks pemain.",
    "add.hint1": "miyoushe tidak punya API pencarian level publik, jadi dipakai jalan memutar: cari postingan → ambil tautan berbagi dari isi postingan → ubah jadi nama sebenarnya. Jadi hanya level yang tautannya pernah dibagikan orang yang bisa ditemukan; tidak ketemu bukan berarti levelnya tidak ada — gunakan cara 2 di bawah.",
    "add.hint2": "Cara menemukan ID level: buka halaman level dan lihat bilah alamat — angka setelah level_id= (web) atau id= (tautan berbagi dalam game) adalah ID-nya. Kamu bisa menempelkan angka itu saja ke kotak di atas; tautan lengkap tidak wajib.",
    "add.hint3": "Tempel tautan HoYoLAB lengkap atau pilih wilayah sebelum memasukkan ID. CN dan Global mencoba akses langsung lalu mencari proksi sistem, config/proxy.txt dan port lokal jika gagal. Alat ini tidak menyediakan server proksi. Tab Global menggunakan ID atau tautan.",
    "btn.gotIt": "Mengerti",
