    "onboard.intro": "Selamat datang! Bahasa antarmuka langsung berubah setelah dipilih. Anda dapat mengubahnya lagi di kanan atas. Komentar asli tidak diterjemahkan oleh pengaturan ini.",
    "onboard.cn": "Bahasa Mandarin sederhana membuka formulir server Tiongkok secara default. Pilih server, lalu cari dengan ID level atau tautan berbagi.",
    "onboard.os": "Bahasa ini membuka formulir server global secara default. Tambahkan level, pilih Asia, Eropa, Amerika, atau Taiwan/Hong Kong/Makau, lalu cari dengan ID atau tautan HoYoLAB. Anda juga dapat beralih ke server Tiongkok secara manual.",
    "onboard.sync": "Setelah pencarian, konfirmasi grup lalu tambahkan dan sinkronkan. Selanjutnya sinkronkan komentar terbaru atau muat ulang seluruh koleksi untuk memperbarui konten lama. Jika koneksi langsung gagal, alat memberi tahu dan mencoba proxy lokal yang tersedia. Gunakan bintang untuk menyimpan catatan.",
