    "batch.keepOpen": "Biarkan jendela ini terbuka setelah impor",
    "onboard.realIntro": "Pilih bahasa. Kita akan mengimpor komentar nyata, mencoba filter, menyimpan komentar, dan menulis catatan. Data disimpan secara lokal. Anda bisa melanjutkan nanti.",
    "onboard.importHelp": "Pilih wilayah, tempel ID atau tautan Anda, lalu cari untuk memastikan level sebelum menambahkan dan menyinkronkan. Mandarin sederhana memakai server Tiongkok secara default, bahasa lain memakai global. Pilihan dapat diubah. Pencarian otomatis dimulai setelah jeda mengetik; tombol pencarian atau Enter juga dapat digunakan.",
