    "data.para": "Copie a pasta inteira para reutilizar (requer Node.js). Para entregar sem os seus dados, use «Apagar dados» acima ou elimine a pasta data.",
    "unit.listSep": ", ",
    "grp.current": " (atual)",
    "tpl.unclassified": "{src} (sem categoria)",
    "help.1": "Avaliação: positiva / negativa",
    "help.2": "Usa diretamente o campo is_recommend — é o voto positivo/negativo do próprio jogo, não uma estimativa. Maravilhas só tem positiva e negativa, não há neutra.",
    "help.3": "is_recommend=true significa positivo; false, negativo. A percentagem oficial vem da API do nível. Se faltar, mostra-se a local; os conjuntos de avaliações podem diferir.",
    "help.4": "O que são comentários por defeito",
    "help.5": "Se o jogador enviar uma avaliação positiva ou negativa sem texto, o jogo pode publicar uma frase predefinida. Por isso surgem comentários repetidos como estes:",
    "help.6": "非常优秀的奇域，推荐大家游玩~ (zh · positiva)　奇域仍有待打磨，期待作者的更新~ (zh · negativa)",
    "help.7": "A frase predefinida não contém detalhes próprios, mas a avaliação pode refletir uma escolha real. Oculte os modelos para ler opiniões concretas; as suas avaliações não são automaticamente inválidas.",
    "help.8": "Estão incluídos modelos conhecidos em vários idiomas, incluindo chinês simplificado e tradicional. Seguem-se exemplos originais:",
    "help.9": "An outstanding Wonderland! Highly recommended for everyone to try~ (en)　Потрясающий предел! Настоятельно рекомендуем всем! (ru)　とても素晴らしい幻境ですので、皆さんにもオススメです～ (ja)",
    "help.10": "Frases desconhecidas ou alteradas são estimadas pela frequência e outras condições. Pode haver classificações erradas; consulte o original se necessário.",
    "help.11": "Para que serve «Ocultar modelos»",
    "help.12": "Oculta comentários classificados como modelos puros e mantém o texto acrescentado pelo jogador. A classificação automática pode errar.",
    "help.13": "Desative a ocultação de modelos para filtrar cada categoria: Modelos positivos / Modelos negativos / Só texto próprio",
    "help.14": "O que é o «limiar de modelo»",
    "help.15": "O limiar predefinido é 8. Após remover alguns sinais e espaços, um texto desconhecido é considerado um possível modelo se atingir esse número de repetições, tiver pelo menos 12 caracteres e avaliações coincidentes em pelo menos 90%. Os modelos conhecidos não exigem esta frequência.",
    "help.16": "A frequência ajuda a encontrar possíveis modelos novos, mas a repetição por si só não comprova origem oficial.",
    "help.17": "Baixar o limiar torna a deteção de textos desconhecidos mais sensível, com mais falsos positivos. Não afeta os modelos conhecidos.",
    "help.18": "Mais alto é mais conservador: só conta repetição massiva, e os modelos falhados contam como comentários normais.",
    "help.19": "Recalculado de imediato após alterar; não é preciso recolher de novo.",
    "help.20": "Notas",
    "help.21": "Clique em ☆ no canto superior direito de um cartão para o guardar no separador Notas. Pode acrescentar uma observação sua; «Ir ao comentário» volta à lista e destaca-o. A nota guarda também uma cópia do comentário — mesmo que o original seja apagado, o texto continua lá.",
    "help.22": "A sincronização é rápida?",
    "help.23": "Sincronizar: incremental, só o novo. Normalmente 1–2 segundos.",
    "help.24": "A recolha completa executa até seis segmentos por número de comentário e um fluxo por popularidade em paralelo. O tempo e a cobertura dependem da rede e da API; não se garante duração fixa nem 100% de cobertura.",
    "help.25": "Respostas nos comentários",
    "help.26": "As respostas sob cada comentário também são recolhidas e mostradas, mas podem ficar incompletas. A causa é a própria API:",
    "help.27": "A ordem cronológica pode omitir comentários, e o número de respostas pode variar entre resultados da API.",
    "help.28": "A ordem por popularidade pode recuperar alguns comentários omitidos, mas as respostas podem ser apenas pré-visualizações.",
    "help.29": "Experimentei o endpoint dedicado sub_replies: os parâmetros passam a validação (já não dá «parâmetro inválido»), mas o servidor devolve sempre fatal error — pode exigir sessão iniciada, ou faltar um campo que não se consegue descobrir.",
    "help.30": "Quando um comentário surge em várias ordenações, os campos são atualizados e mantêm-se as respostas mais completas recebidas. Podem faltar respostas que a API não devolva.",
    "help.31": "Filtro por intervalo de datas",
    "help.32": "As datas incluem o dia inteiro e pode preencher apenas um extremo. O resumo indica o número de resultados e o intervalo. Limpar apaga apenas as datas, mantendo palavras-chave e filtros de avaliação.",
    "help.33": "O que acontece ao fechar a página",
    "help.34": "O iniciador predefinido oculta a consola. Com saída automática, o serviço termina cerca de três segundos após fechar a página normalmente; um tempo limite de verificação cobre fechos anormais. O modo permanente altera-se em Gestão.",
    "app.title": "Recolhedor de comentários",
    "tpl.explain": "Aqui agrupam-se modelos conhecidos e frases frequentes. A deteção por frequência é uma estimativa: um limiar baixo deteta mais, mas pode errar; um alto pode omitir modelos. O texto acrescentado pelo jogador conta como texto próprio.",
    "add.hint1": "O miyoushe não tem API pública de pesquisa de níveis, por isso contorna-se: pesquisar publicações → extrair do texto os links partilhados → resolver para o nome real. Só se encontram níveis para os quais alguém já partilhou um link; não encontrar não significa que o nível não exista — use a opção 2 abaixo.",
    "add.hint2": "Como encontrar o ID do nível: abra a página do nível e veja a barra de endereço — o número após level_id= (web) ou id= (ligação partilhada no jogo) é o ID. Pode colar apenas esse número na caixa acima; a ligação completa não é necessária.",
    "add.hint3": "Cole uma ligação HoYoLAB completa ou escolha a região antes de introduzir o ID. CN e Global tentam primeiro acesso direto e, se falhar, procuram o proxy do sistema, config/proxy.txt e portas locais. A ferramenta não fornece nós proxy. O separador Global usa IDs ou ligações.",
    "btn.gotIt": "Entendido",
    "status.stayOn": "Alterado: fecha com a página",
