    "onboard.intro": "Bem-vindo! O idioma é aplicado imediatamente. Pode alterá-lo no canto superior direito. Os comentários originais não são traduzidos.",
    "onboard.cn": "O chinês simplificado abre o formulário dos servidores chineses. Escolha o servidor e pesquise um ID de nível ou uma ligação de partilha.",
    "onboard.os": "Este idioma abre o formulário global por predefinição. Adicione um nível, escolha Ásia, Europa, América ou Taiwan/Hong Kong/Macau e pesquise o ID ou a ligação do HoYoLAB. Também pode mudar manualmente para os servidores chineses.",
    "onboard.sync": "Após a pesquisa, confirme o grupo e adicione o nível com sincronização. Depois sincronize os novos comentários ou atualize toda a coleção. Se a ligação direta falhar, surge um aviso e são tentados os proxies locais existentes. Use a estrela para guardar notas.",
