    "lookup.network": "O pedido de rede não terminou. O nível ainda não foi verificado; verifique a ligação e tente novamente.",
    "batch.keepOpen": "Manter esta janela aberta após importar",
    "onboard.realIntro": "Escolha um idioma. Vamos importar comentários reais, experimentar filtros e guardar um comentário com uma nota pessoal. Os dados ficam guardados localmente. Pode continuar mais tarde.",
    "onboard.importHelp": "Escolha a região, cole o seu ID ou ligação e confirme o nível antes de adicionar e sincronizar. O chinês simplificado começa nos servidores chineses; os outros idiomas, nos globais. Pode mudar. A pesquisa começa após uma breve pausa na escrita; também pode usar o botão ou Enter.",
    "onboard.syncWait": "A descarregar comentários. Acompanhe o registo na página principal. O guia continua após confirmar a gravação.",
    "onboard.syncRetry": "A primeira sincronização falhou. Verifique o registo, a rede ou o proxy e tente novamente. O nível continua registado.",
    "onboard.empty": "A sincronização terminou sem comentários disponíveis. Escolha um nível com comentários ou tente mais tarde. O guia ainda não está concluído.",
    "onboard.labelsTitle": "Etiquetas e filtros",
    "onboard.labelsBody": "As etiquetas positivas e negativas seguem as avaliações oficiais. Os modelos são detetados automaticamente e podem estar errados. Clique num filtro ou oculte modelos e observe a lista.",
    "onboard.saveTitle": "Guardar um comentário",
    "onboard.saveBody": "Clique em ☆ num comentário para guardar uma cópia nas notas. Depois clique em Seguinte para confirmar a gravação.",
