    "data.port": "Bağlantı noktası: {port} (yalnız yerel)",
    "data.para": "Başka yerde kullanmak için tüm klasörü kopyalayın (Node.js gerekir). Verileriniz olmadan devretmek için yukarıdaki \"Verileri sil\"i kullanın veya data klasörünü silin.",
    "unit.listSep": ", ",
    "grp.current": " (geçerli)",
    "tpl.unclassified": "{src} (sınıflandırılmamış)",
    "help.1": "Değerlendirme: olumlu / olumsuz",
    "help.2": "Doğrudan is_recommend alanı kullanılıyor: bu, oyunun kendi olumlu/olumsuz oyu, tahmin değil. Harikalar Diyarı’nda yalnızca olumlu ve olumsuz var, nötr yok.",
    "help.3": "is_recommend=true olumlu, false olumsuz demektir. Resmî olumlu oranı seviye API’sinden gelir. Yoksa yerel oran gösterilir; sayılan değerlendirmelerin kapsamı farklı olabilir.",
    "help.4": "Varsayılan yorum nedir",
    "help.5": "Oyuncu metin yazmadan olumlu veya olumsuz değerlendirme gönderirse oyun hazır bir cümle yayımlayabilir. Böylece şu tür tekrarlanan yorumlar oluşur:",
    "help.6": "非常优秀的奇域，推荐大家游玩~ (zh · olumlu)　奇域仍有待打磨，期待作者的更新~ (zh · olumsuz)",
    "help.7": "Hazır cümle ayrıntılı görüş içermez, ancak değerlendirme oyuncunun gerçek seçimini yansıtabilir. Belirli geri bildirimleri okumak için şablonları gizleyin; bu değerlendirmeler kendiliğinden geçersiz değildir.",
    "help.8": "Basitleştirilmiş ve Geleneksel Çince dahil birçok dil için bilinen şablonlar bulunur. Aşağıda özgün örnekler vardır:",
    "help.9": "An outstanding Wonderland! Highly recommended for everyone to try~ (en)　Потрясающий предел! Настоятельно рекомендуем всем! (ru)　とても素晴らしい幻境ですので、皆さんにもオススメです～ (ja)",
    "help.10": "Bilinmeyen veya değişmiş metinler, sıklık ve diğer koşullarla tahmin edilir. Yanlış sınıflandırma olabilir; gerektiğinde özgün metni kontrol edin.",
    "help.11": "\"Şablonları gizle\" ne yapar",
    "help.12": "Saf şablon olarak sınıflandırılan yorumları gizler, oyuncunun eklediği metni korur. Otomatik sınıflandırma yanlış olabilir.",
    "help.13": "Kategorileri ayrı görmek için şablonları gizlemeyi kapatın: Olumlu şablonlar / Olumsuz şablonlar / Yalnız kendi metni",
    "help.14": "\"Şablon eşiği\" nedir",
    "help.15": "Varsayılan eşik 8’dir. Bazı noktalama ve boşluklar çıkarıldıktan sonra bilinmeyen metin, en az eşik kadar tekrarlanıyor, en az 12 karakter içeriyor ve değerlendirmelerin en az %90’ı aynıysa olası şablon sayılır. Bilinen şablonlar bu sıklığı gerektirmez.",
    "help.16": "Sıklık, bilinmeyen olası şablonları bulmaya yardımcı olur; tek başına tekrar resmî kaynağı kanıtlamaz.",
    "help.17": "Eşiği düşürmek bilinmeyen metinleri daha hassas algılar ancak oyuncunun tekrarladığı sözleri yanlış sınıflandırabilir. Bilinen şablon eşleşmeleri etkilenmez.",
    "help.18": "Yüksek değer daha muhafazakâr: yalnızca büyük tekrarlar sayılır, kaçırılan şablonlar normal yorum olarak istatistiğe girer.",
    "help.19": "Değiştirince hemen yeniden hesaplanır; veriyi tekrar çekmek gerekmez.",
    "help.20": "Notlar",
    "help.21": "Bir yorum kartının sağ üstündeki ☆ simgesine basarak Notlar sekmesine kaydedin. Kendi notunuzu ekleyebilirsiniz; \"Yoruma git\" listeye dönüp o satırı vurgular. Not, yorumun bir kopyasını da saklar — orijinal silinse bile metin durur.",
    "help.22": "Eşitleme ne kadar hızlı",
    "help.23": "Yenileri eşitle: artımlı, yalnızca yeniler. Genelde 1–2 saniye.",
    "help.24": "Tam toplama, yorum numarasına göre en fazla altı bölüm ve bir popülerlik akışını paralel çalıştırır. Süre ve kapsam ağ ile API yanıtlarına bağlıdır; sabit süre veya %100 kapsam garanti edilmez.",
    "help.25": "Yorum altı yanıtlar",
    "help.26": "Yorumların altındaki yanıtlar da çekilip gösterilir, ancak eksik olabilir. Nedeni API’nin kendisi:",
    "help.27": "Zaman sıralaması bazı yorumları atlayabilir; dönen yanıt sayısı API sonuçlarına göre değişebilir.",
    "help.28": "Popülerlik sıralaması eksik yorumların bir kısmını tamamlayabilir, ancak yanıtlar yalnızca önizleme olabilir.",
    "help.29": "Özel sub_replies uç noktasını denedim: parametreler doğrulamayı geçiyor (\"geçersiz parametre\" hatası artık yok), ama sunucu her zaman fatal error döndürüyor — oturum açmış olmak gerekebilir veya bulunamayan bir alan daha eksik olabilir.",
    "help.30": "Aynı yorum farklı sıralamalarda dönerse alanları güncellenir ve daha eksiksiz yanıtlar korunur. API’nin döndürmediği yanıtlar eksik kalabilir.",
    "help.31": "Tarih aralığı süzgeci",
    "help.32": "İki tarih de günün tamamını kapsar; tek sınır girilebilir. Özet eşleşme sayısını ve aralığı gösterir. Temizle yalnız tarihleri siler; arama sözcükleri ve değerlendirme filtreleri kalır.",
    "help.33": "Sayfayı kapatınca ne olur",
    "help.34": "Varsayılan başlatıcı konsolu gizler. Otomatik çıkış açıkken sayfa normal kapatıldıktan yaklaşık üç saniye sonra arka plan hizmeti durur; anormal kapanmalar bağlantı kontrolü zaman aşımıyla ele alınır. Kalıcı mod Yönet bölümünden değiştirilir.",
    "app.title": "Yorum Toplayıcı",
    "tpl.explain": "Bilinen şablonlar ve sık tekrarlanan metinler burada gruplanır. Sıklık algılama bir tahmindir: düşük eşik daha çok bulur ama yanılabilir; yüksek eşik şablonları kaçırabilir. Oyuncunun eklediği metin, kendi metni sayılır.",
    "add.hint1": "miyoushe'in herkese açık bir seviye arama API'si yok, bu yüzden dolambaçlı yol kullanılıyor: gönderilerde ara → gönderi metninden başkalarının paylaştığı bağlantıları çıkar → gerçek ada çevir. Bu yüzden yalnızca birinin bağlantı paylaştığı seviyeler bulunabilir; bulunamaması seviyenin olmadığı anlamına gelmez — aşağıdaki 2. yolu kullanın.",
    "add.hint2": "Seviye kimliğini bulma: seviye sayfasını açıp adres çubuğuna bakın — level_id= (web) veya id= (oyun içi paylaşım bağlantısı) sonrasındaki sayı kimliktir. Sadece bu sayıyı yukarıdaki kutuya yapıştırabilirsiniz; tam bağlantı şart değil.",
    "add.hint3": "Tam HoYoLAB bağlantısını yapıştırın veya kimlikten önce doğru bölgeyi seçin. CN ve Global önce doğrudan erişimi, başarısız olursa sistem proxy’sini, config/proxy.txt dosyasını ve yerel portları dener. Araç proxy düğümü sağlamaz. Global sekmesi kimlik veya bağlantı kullanır.",
