    "onboard.cn": "Basitleştirilmiş Çince, varsayılan olarak Çin sunucusu formunu açar. Sunucuyu seçip bölüm kimliği veya paylaşım bağlantısıyla sorgulayın.",
    "onboard.os": "Bu dilde varsayılan olarak küresel sunucu formu açılır. Bölüm ekleyin; Asya, Avrupa, Amerika veya Tayvan/Hong Kong/Makao seçip bölüm kimliği ya da HoYoLAB bağlantısıyla sorgulayın. Çin sunucularına elle de geçebilirsiniz.",
    "onboard.sync": "Sorgudan sonra grubu onaylayıp bölümü eşitleyerek ekleyin. Daha sonra yeni yorumları eşitleyin veya mevcut içeriği güncellemek için tümünü yeniden alın. Doğrudan bağlantı başarısız olursa bildirim gösterilir ve mevcut yerel proxy sunucuları denenir. Yıldızla not kaydedebilirsiniz.",
