    "data.para": "Copia l’intera cartella per riusarla altrove (serve Node.js). Per cedere lo strumento senza i tuoi dati, usa «Elimina dati» o cancella la cartella data.",
    "unit.listSep": ", ",
    "grp.current": " (attuale)",
    "tpl.unclassified": "{src} (non classificato)",
    "help.1": "Valutazione: positiva / negativa",
    "help.2": "Si usa direttamente il campo is_recommend: è il voto positivo/negativo del gioco stesso, non una stima. Meraviglie ha solo positiva e negativa, non esiste il neutro.",
    "help.3": "is_recommend=true significa positivo; false, negativo. La percentuale ufficiale viene dall’API del livello. Se manca, si mostra quella locale; gli insiemi di valutazioni possono differire.",
    "help.4": "Cosa sono i commenti predefiniti",
    "help.5": "Se il giocatore invia una valutazione positiva o negativa senza testo, il gioco può pubblicare una frase predefinita. Questo genera commenti ripetuti come questi:",
    "help.6": "非常优秀的奇域，推荐大家游玩~ (zh · positiva)　奇域仍有待打磨，期待作者的更新~ (zh · negativa)",
    "help.7": "La frase predefinita non contiene dettagli personali, ma la valutazione può riflettere una scelta reale. Nascondi i modelli per leggere opinioni specifiche; le loro valutazioni non sono automaticamente invalide.",
    "help.8": "Sono inclusi modelli noti per varie lingue, tra cui cinese semplificato e tradizionale. Seguono esempi originali:",
    "help.9": "An outstanding Wonderland! Highly recommended for everyone to try~ (en)　Потрясающий предел! Настоятельно рекомендуем всем! (ru)　とても素晴らしい幻境ですので、皆さんにもオススメです～ (ja)",
    "help.10": "Le frasi sconosciute o modificate vengono stimate in base a frequenza e altre condizioni. La classificazione può sbagliare; controlla il testo originale se necessario.",
    "help.11": "A cosa serve «Nascondi modelli»",
    "help.12": "Nasconde i commenti classificati come modelli puri e mantiene il testo aggiunto dal giocatore. La classificazione automatica può sbagliare.",
    "help.13": "Disattiva il filtro dei modelli per vedere le categorie separatamente: Modelli positivi / Modelli negativi / Solo testo proprio",
    "help.14": "Cos’è la «soglia modello»",
    "help.15": "La soglia predefinita è 8. Dopo aver rimosso alcuni segni e spazi, un testo sconosciuto viene considerato un possibile modello se raggiunge tale numero di ripetizioni, è lungo almeno 12 caratteri e presenta valutazioni concordi almeno al 90%. I modelli noti non richiedono questa frequenza.",
    "help.16": "La frequenza aiuta a trovare possibili modelli nuovi, ma la ripetizione da sola non dimostra un’origine ufficiale.",
    "help.17": "Abbassare la soglia rende più sensibile il rilevamento di testi sconosciuti e aumenta i falsi positivi. Non influisce sui modelli noti.",
    "help.18": "Più alto è più prudente: contano solo le ripetizioni massicce e i modelli mancati vengono contati come commenti normali.",
    "help.19": "Ricalcolato subito dopo la modifica, senza dover riscaricare i dati.",
    "help.20": "Note",
    "help.21": "Fai clic su ☆ in alto a destra di una scheda per salvarla nella scheda Note. Puoi aggiungere un tuo commento; «Vai al commento» torna all’elenco e lo evidenzia. La nota conserva anche una copia del commento: anche se l’originale viene eliminato, il testo resta.",
    "help.22": "Quanto è veloce la sincronizzazione",
    "help.23": "Sincronizza: incrementale, solo i nuovi. Di solito 1–2 secondi.",
    "help.24": "La raccolta completa esegue in parallelo fino a sei segmenti per numero di commento e un flusso per popolarità. Tempo e completezza dipendono dalla rete e dall’API; non sono garantiti tempi fissi né copertura al 100%.",
    "help.25": "Risposte sotto i commenti",
    "help.26": "Anche le risposte sotto i commenti vengono raccolte e mostrate, ma possono essere incomplete. Il motivo è l’API stessa:",
    "help.27": "L’ordine cronologico può omettere commenti e il numero di risposte può variare tra i risultati dell’API.",
    "help.28": "L’ordine per popolarità può recuperare alcuni commenti omessi, ma le risposte possono essere soltanto anteprime.",
    "help.29": "Ho provato l’endpoint dedicato sub_replies: i parametri passano la validazione (niente più «invalid parameter»), ma il server restituisce sempre fatal error — forse serve una sessione autenticata, o manca un campo non individuabile.",
    "help.30": "Quando un commento arriva da ordinamenti diversi, i campi vengono aggiornati e si conservano le risposte più complete ricevute. Le risposte omesse dall’API possono restare mancanti.",
    "help.31": "Filtro per intervallo di date",
    "help.32": "Le date includono l’intera giornata e puoi inserire un solo limite. Il riepilogo mostra corrispondenze e intervallo. Pulisci cancella solo le date; parole chiave e filtri di valutazione restano.",
    "help.33": "Cosa succede chiudendo la pagina",
    "help.34": "L’avvio predefinito nasconde la console. Con uscita automatica, il servizio si ferma circa tre secondi dopo la chiusura normale della pagina; un controllo di connessione gestisce le chiusure anomale tramite timeout. La modalità permanente si cambia in Gestione.",
    "app.title": "Raccolta commenti",
    "tpl.explain": "Qui sono raggruppati modelli noti e frasi frequenti. Il rilevamento per frequenza è una stima: una soglia bassa trova più casi ma può sbagliare; una alta può perdere modelli. Le aggiunte del giocatore contano come testo proprio.",
    "add.hint1": "miyoushe non espone un’API pubblica di ricerca livelli, quindi si aggira il problema: cerca post → estrai dal testo i link condivisi → risolvili in nomi reali. Si trovano solo i livelli per cui qualcuno ha condiviso un link; non trovarli non significa che non esistano: usa l’opzione 2 qui sotto.",
    "add.hint2": "Come trovare l’ID del livello: apri la pagina del livello e guarda la barra degli indirizzi — il numero dopo level_id= (web) o id= (link condiviso in gioco) è l’ID. Puoi incollare solo quel numero nella casella sopra; il link completo non serve.",
    "add.hint3": "Incolla un link HoYoLAB completo o scegli la regione prima di inserire l’ID. CN e Global provano prima l’accesso diretto e, se fallisce, cercano proxy di sistema, config/proxy.txt e porte locali. Lo strumento non fornisce nodi proxy. La scheda Global usa ID o link.",
    "btn.gotIt": "Ho capito",
