  const themeKeys=["ocean","forest","light","ember","water","sakura","washi","violet","geo","whale","butterflies","waterEffect","leaves","petals","snow","lightning","lantern","cubes","dream"]
  for(const [lang,text] of Object.entries(themeLabels)){
    const values=text.split('|')
    if(values.length!==themeKeys.length)throw new Error('Theme translation length: '+lang)
    themeKeys.forEach((key,i)=>{QX_I18N[lang]['appearance.'+key]=values[i]})
  }
  const releaseHints={"zh-cn":"分享或上传前，请运行 app/launcher/prepare-release.ps1 创建不含个人数据的独立发布副本；不要删除当前工作目录里的评论或便签。接收方需要安装 Node.js。","zh-tw":"分享或上傳前，請執行 app/launcher/prepare-release.ps1 建立不含個人資料的獨立發佈副本；請勿刪除工作目錄中的評論或便箋。接收方需要安裝 Node.js。","en-us":"Before sharing or uploading, run app/launcher/prepare-release.ps1 to create a separate distribution without personal data. Keep the working comments and notes. Recipients need Node.js.","ja-jp":"共有・アップロード前に app/launcher/prepare-release.ps1 で個人データを含まない配布用コピーを作成してください。作業中のコメントやメモは削除しないでください。利用先には Node.js が必要です。","ko-kr":"공유하거나 업로드하기 전에 app/launcher/prepare-release.ps1로 개인 데이터가 없는 별도 배포본을 만드세요. 작업 중인 댓글과 메모는 삭제하지 마세요. 받는 사람은 Node.js가 필요합니다.","es-es":"Antes de compartir o subir archivos, ejecuta app/launcher/prepare-release.ps1 para crear una copia sin datos personales. Conserva los comentarios y notas de trabajo. Se necesita Node.js.","fr-fr":"Avant de partager ou publier, lancez app/launcher/prepare-release.ps1 pour créer une copie sans données personnelles. Conservez vos commentaires et notes de travail. Node.js est requis.","ru-ru":"Перед публикацией запустите app/launcher/prepare-release.ps1 для создания отдельной копии без личных данных. Сохраните рабочие комментарии и заметки. Получателям нужен Node.js.","th-th":"ก่อนแชร์หรืออัปโหลด ให้รัน app/launcher/prepare-release.ps1 เพื่อสร้างสำเนาเผยแพร่แยกต่างหากที่ไม่มีข้อมูลส่วนตัว อย่าลบความคิดเห็นหรือบันทึกที่ใช้งาน ผู้รับต้องติดตั้ง Node.js","vi-vn":"Trước khi chia sẻ hoặc tải lên, chạy app/launcher/prepare-release.ps1 để tạo bản phát hành riêng không có dữ liệu cá nhân. Giữ lại bình luận và ghi chú đang dùng. Người nhận cần Node.js.","de-de":"Vor dem Teilen oder Hochladen mit app/launcher/prepare-release.ps1 eine separate Kopie ohne persönliche Daten erstellen. Arbeitskommentare und Notizen behalten. Empfänger benötigen Node.js.","id-id":"Sebelum berbagi atau mengunggah, jalankan app/launcher/prepare-release.ps1 untuk membuat salinan distribusi terpisah tanpa data pribadi. Simpan komentar dan catatan kerja. Penerima memerlukan Node.js.","pt-pt":"Antes de partilhar ou carregar, executa app/launcher/prepare-release.ps1 para criar uma cópia separada sem dados pessoais. Mantém os comentários e notas de trabalho. É necessário Node.js.","tr-tr":"Paylaşmadan veya yüklemeden önce app/launcher/prepare-release.ps1 ile kişisel veri içermeyen ayrı bir dağıtım kopyası oluşturun. Çalışma yorumlarını ve notlarını koruyun. Alıcılara Node.js gerekir.","it-it":"Prima di condividere o caricare, esegui app/launcher/prepare-release.ps1 per creare una copia separata senza dati personali. Conserva i commenti e le note di lavoro. È necessario Node.js."}
  for(const [lang,text] of Object.entries(releaseHints))QX_I18N[lang]['data.para']=text
  const unreadHoverLabels={"zh-cn":"更新优先|只看更新|每次重新打开或刷新页面后，各关卡首次完整成功同步会自动清除上一轮标记，只保留本轮新增；本次打开内后续同步继续累积。同步失败或回复未取完时保留旧标记。其他筛选仍生效，必要时保留回复上文。|更新评论 {n} · 更新回复 {s}|更新评论|更新回复|本次同步新增评论 {n} · 回复 {s}|按钮悬浮反馈|自动跟随主题|自定义颜色|悬浮背景色|清除当前关卡的全部更新标记；总览下清除整组，不受筛选限制。评论和便签不会删除。","zh-tw":"更新優先|只看更新|每次重新開啟或重新整理頁面後，各關卡首次完整成功同步會自動清除上一輪標記，只保留本輪新增；本次開啟內後續同步繼續累積。同步失敗或回覆未取完時保留舊標記。其他篩選仍生效，必要時保留回覆上文。|更新評論 {n} · 更新回覆 {s}|更新評論|更新回覆|本次同步新增評論 {n} · 回覆 {s}|按鈕懸停回饋|自動跟隨主題|自訂顏色|懸停背景色|清除目前關卡的全部更新標記；總覽下清除整組，不受篩選限制。不會刪除評論或便箋。","en-us":"Updates first|Updates only|After reopening or reloading, each entry’s first fully successful sync clears previous-round markers and keeps this round’s additions. Later syncs accumulate. Failed or incomplete reply syncs keep older markers. Other filters apply; reply context may remain.|Comment updates {n} · Reply updates {s}|Comment update|Reply update|This sync: {n} new comments · {s} new replies|Button hover feedback|Follow theme|Custom color|Hover background|Clear all update markers for the selected entry or entire overview group, regardless of filters. Comments and notes are kept.","ja-jp":"更新を優先|更新のみ|ページを開き直すか再読み込みした後、各項目の最初の完全な同期成功で前回のマークを解除し、今回の追加分を残します。その後の同期は累積します。失敗や返信の取得未完了では前回分を保持します。他の絞り込みも適用されます。|更新コメント {n} · 更新返信 {s}|更新コメント|更新返信|今回の同期：新規コメント {n} · 返信 {s}|ボタンのホバー表示|テーマに合わせる|色を指定|ホバー背景色|絞り込みに関係なく選択中の項目、一覧ではグループ全体の更新マークを解除します。コメントとメモは保持します。","ko-kr":"업데이트 우선|업데이트만|페이지를 다시 열거나 새로고침한 후 각 항목의 첫 완전한 동기화 성공 시 이전 표시를 지우고 이번 추가분을 유지합니다. 이후 동기화는 누적됩니다. 실패하거나 답글 수집이 미완료이면 이전 표시를 유지합니다. 다른 필터도 적용됩니다.|업데이트 댓글 {n} · 답글 {s}|업데이트 댓글|업데이트 답글|이번 동기화: 새 댓글 {n} · 답글 {s}|버튼 호버 효과|테마에 맞춤|사용자 지정 색상|호버 배경색|필터와 관계없이 선택 항목 또는 모아보기 그룹 전체의 업데이트 표시를 지웁니다. 댓글과 메모는 유지됩니다.","es-es":"Actualizaciones primero|Solo actualizaciones|Al reabrir o recargar, la primera sincronización completa de cada entrada borra las marcas anteriores y conserva las novedades de esta sesión. Las siguientes acumulan. Los fallos o respuestas incompletas conservan las marcas anteriores. Se aplican otros filtros.|Comentarios actualizados {n} · Respuestas {s}|Comentario actualizado|Respuesta actualizada|Esta sincronización: {n} comentarios nuevos · {s} respuestas nuevas|Efecto al pasar el cursor|Seguir tema|Color personalizado|Fondo al pasar el cursor|Borra las marcas de toda la entrada o del grupo seleccionado, independientemente de los filtros. Conserva comentarios y notas.","fr-fr":"Mises à jour en premier|Mises à jour uniquement|Après réouverture ou rechargement, la première synchronisation complète de chaque entrée efface les anciens marqueurs et garde les ajouts de cette session. Les suivantes cumulent les ajouts. Les échecs ou réponses incomplètes conservent les anciens marqueurs. Les autres filtres restent actifs.|Commentaires mis à jour {n} · Réponses {s}|Commentaire mis à jour|Réponse mise à jour|Cette synchronisation : {n} nouveaux commentaires · {s} nouvelles réponses|Retour au survol des boutons|Suivre le thème|Couleur personnalisée|Fond au survol|Efface les marqueurs de toute l’entrée ou du groupe sélectionné, indépendamment des filtres. Les commentaires et notes sont conservés.","ru-ru":"Сначала обновления|Только обновления|После повторного открытия или перезагрузки первая полная успешная синхронизация записи снимает старые метки и сохраняет добавления этого сеанса. Следующие синхронизации накапливают их. Ошибки или неполные ответы сохраняют старые метки. Другие фильтры действуют.|Обновления комментариев {n} · Ответов {s}|Обновление комментария|Обновление ответа|Эта синхронизация: новых комментариев {n} · ответов {s}|Реакция кнопок на наведение|По теме|Свой цвет|Фон при наведении|Снимает все метки выбранной записи или всей группы независимо от фильтров. Комментарии и заметки сохраняются.","th-th":"อัปเดตก่อน|เฉพาะอัปเดต|เมื่อเปิดหรือโหลดหน้าใหม่ การซิงค์สำเร็จครบถ้วนครั้งแรกของแต่ละรายการจะล้างเครื่องหมายรอบก่อนและเก็บรายการใหม่ของรอบนี้ การซิงค์ถัดไปจะสะสม หากล้มเหลวหรือคำตอบยังไม่ครบจะเก็บเครื่องหมายเดิม ตัวกรองอื่นยังมีผล|ความคิดเห็นอัปเดต {n} · คำตอบ {s}|ความคิดเห็นอัปเดต|คำตอบอัปเดต|การซิงค์ครั้งนี้: ความคิดเห็นใหม่ {n} · คำตอบใหม่ {s}|เอฟเฟกต์เมื่อชี้ปุ่ม|ตามธีม|สีที่กำหนดเอง|พื้นหลังเมื่อชี้|ล้างเครื่องหมายอัปเดตของรายการหรือทั้งกลุ่มที่เลือกโดยไม่จำกัดตามตัวกรอง ความคิดเห็นและบันทึกยังอยู่","vi-vn":"Ưu tiên cập nhật|Chỉ cập nhật|Sau khi mở lại hoặc tải lại trang, lần đồng bộ hoàn tất đầu tiên của mỗi mục xóa dấu cũ và giữ phần mới của phiên này. Các lần sau tiếp tục cộng dồn. Lỗi hoặc trả lời chưa đủ sẽ giữ dấu cũ. Các bộ lọc khác vẫn áp dụng.|Bình luận cập nhật {n} · Trả lời {s}|Bình luận cập nhật|Trả lời cập nhật|Lần đồng bộ này: {n} bình luận mới · {s} trả lời mới|Hiệu ứng khi rê lên nút|Theo giao diện|Màu tùy chỉnh|Nền khi rê chuột|Xóa mọi dấu cập nhật của mục hoặc toàn nhóm đang chọn, không phụ thuộc bộ lọc. Giữ nguyên bình luận và ghi chú.","de-de":"Aktualisierungen zuerst|Nur Aktualisierungen|Nach erneutem Öffnen oder Laden löscht der erste vollständig erfolgreiche Abgleich jedes Eintrags alte Markierungen und behält neue dieser Sitzung. Weitere Abgleiche sammeln sie. Fehler oder unvollständige Antworten behalten alte Markierungen. Andere Filter gelten weiter.|Kommentaraktualisierungen {n} · Antworten {s}|Kommentaraktualisierung|Antwortaktualisierung|Dieser Abgleich: {n} neue Kommentare · {s} neue Antworten|Schaltflächen bei Mauszeigerkontakt|Dem Design folgen|Eigene Farbe|Hintergrund bei Mauszeigerkontakt|Entfernt alle Markierungen des gewählten Eintrags oder der gesamten Gruppe unabhängig von Filtern. Kommentare und Notizen bleiben erhalten.","id-id":"Pembaruan dahulu|Hanya pembaruan|Setelah membuka atau memuat ulang, sinkronisasi pertama yang sepenuhnya berhasil untuk setiap entri menghapus tanda lama dan menyimpan tambahan sesi ini. Sinkronisasi selanjutnya mengumpulkan tambahan. Kegagalan atau balasan tidak lengkap mempertahankan tanda lama. Filter lain tetap berlaku.|Pembaruan komentar {n} · Balasan {s}|Pembaruan komentar|Pembaruan balasan|Sinkronisasi ini: {n} komentar baru · {s} balasan baru|Efek saat kursor di tombol|Ikuti tema|Warna khusus|Latar saat kursor di tombol|Hapus semua tanda pembaruan entri atau seluruh grup terpilih tanpa batas filter. Komentar dan catatan tetap disimpan.","pt-pt":"Atualizações primeiro|Apenas atualizações|Ao reabrir ou recarregar, a primeira sincronização completa de cada entrada limpa as marcas anteriores e mantém as novidades desta sessão. As seguintes acumulam. Falhas ou respostas incompletas mantêm as marcas anteriores. Os outros filtros continuam ativos.|Comentários atualizados {n} · Respostas {s}|Comentário atualizado|Resposta atualizada|Esta sincronização: {n} comentários novos · {s} respostas novas|Efeito ao passar o cursor|Seguir tema|Cor personalizada|Fundo ao passar o cursor|Remove as marcas de toda a entrada ou grupo selecionado, independentemente dos filtros. Mantém comentários e notas.","tr-tr":"Önce güncellemeler|Yalnız güncellemeler|Yeniden açma veya yükleme sonrası her kaydın ilk tamamen başarılı eşitlemesi önceki işaretleri temizler ve bu oturumun eklerini korur. Sonrakiler birikir. Hata veya eksik yanıtlar eski işaretleri korur. Diğer filtreler uygulanır.|Yorum güncellemeleri {n} · Yanıtlar {s}|Yorum güncellemesi|Yanıt güncellemesi|Bu eşitleme: {n} yeni yorum · {s} yeni yanıt|Düğme üzerine gelme efekti|Temayı izle|Özel renk|Üzerine gelme arka planı|Filtrelerden bağımsız olarak seçili kaydın veya tüm grubun işaretlerini temizler. Yorum ve notlar korunur.","it-it":"Prima gli aggiornamenti|Solo aggiornamenti|Dopo riapertura o ricaricamento, la prima sincronizzazione completa di ogni voce cancella i segni precedenti e mantiene le novità della sessione. Le successive accumulano. Errori o risposte incomplete conservano i segni precedenti. Gli altri filtri si applicano.|Commenti aggiornati {n} · Risposte {s}|Commento aggiornato|Risposta aggiornata|Questa sincronizzazione: {n} nuovi commenti · {s} nuove risposte|Effetto al passaggio sui pulsanti|Segui il tema|Colore personalizzato|Sfondo al passaggio|Rimuove tutti i segni della voce o dell’intero gruppo selezionato, indipendentemente dai filtri. Commenti e note restano."}
  const unreadHoverKeys=["new.pin","new.only","new.viewHint","new.summary","new.comment","new.reply","new.syncSummary","appearance.hoverMode","appearance.hoverAuto","appearance.hoverCustom","appearance.hoverColor","new.markReadHint"]
  for(const [lang,text] of Object.entries(unreadHoverLabels)){const values=text.split('|');if(values.length!==unreadHoverKeys.length)throw Error('Unread/hover translation '+lang);unreadHoverKeys.forEach((key,i)=>QX_I18N[lang][key]=values[i])}
