  const replyRelationLabels={"en-us":"Reply to {name}|Reply to main comment|Hover or focus this row to highlight posts by the addressed user in this thread. Multiple posts may match; this does not identify an exact parent reply.","zh-tw":"回覆 {name}|回覆主評論|懸停或聚焦此列，會標示回覆對象在本串的發言；同一作者可能有多則發言，不代表確定回覆了哪一則。","vi-vn":"Trả lời {name}|Trả lời bình luận chính|Rê chuột hoặc đặt tiêu điểm để làm nổi bật bài của người nhận. Có thể có nhiều bài; không xác định chính xác trả lời bài nào.","de-de":"Antwort an {name}|Antwort auf Hauptkommentar|Beim Darüberfahren oder Fokussieren werden Beiträge des Empfängers hervorgehoben. Mehrere können passen; kein genauer Ursprungsbeitrag wird behauptet.","th-th":"ตอบกลับ {name}|ตอบความคิดเห็นหลัก|ชี้หรือโฟกัสแถวนี้เพื่อเน้นข้อความของผู้รับ อาจมีหลายข้อความ จึงไม่ได้ระบุว่าตอบข้อความใดโดยเฉพาะ","fr-fr":"Réponse à {name}|Réponse au commentaire principal|Le survol ou le focus souligne les messages du destinataire. Plusieurs peuvent correspondre ; cela ne désigne pas une réponse précise.","ru-ru":"Ответ пользователю {name}|Ответ на основной комментарий|Наведение или фокус выделяет сообщения адресата. Совпадений может быть несколько; точный исходный ответ не определяется.","it-it":"Risposta a {name}|Risposta al commento principale|Il passaggio o il focus evidenzia i messaggi del destinatario. Possono essere più di uno; non identifica una risposta precisa.","ko-kr":"{name}에게 답글|원댓글에 답글|이 행에 커서를 올리거나 초점을 맞추면 상대 사용자의 글을 강조합니다. 여러 글이 있을 수 있으며 특정 원답글을 뜻하지 않습니다.","tr-tr":"{name} kullanıcısına yanıt|Ana yoruma yanıt|Üzerine gelince veya odaklanınca alıcının iletileri vurgulanır. Birden çok ileti eşleşebilir; kesin üst yanıtı belirtmez.","es-es":"Respuesta a {name}|Respuesta al comentario principal|Al pasar el cursor o enfocar se resaltan los mensajes del destinatario. Puede haber varios; no identifica una respuesta concreta.","ja-jp":"{name} への返信|元コメントへの返信|ホバーまたはフォーカスすると、返信先の人の発言を強調します。同じ人の発言が複数ある場合、特定の返信先を示すものではありません。","pt-pt":"Resposta a {name}|Resposta ao comentário principal|Ao passar o cursor ou focar, destacam-se mensagens do destinatário. Podem existir várias; não identifica uma resposta específica.","zh-cn":"回复 {name}|回复主评论|悬浮或聚焦此行，会高亮回复对象在本串中的发言；同一作者可能有多条发言，不代表确定回复了其中哪一条。","id-id":"Balasan ke {name}|Balasan ke komentar utama|Arahkan kursor atau fokus untuk menyorot pesan penerima. Bisa ada beberapa pesan; ini tidak menunjukkan induk balasan yang pasti."}
  for(const [lang,text] of Object.entries(replyRelationLabels)){const values=text.split('|');['sub.replyTo','sub.replyMain','sub.relationHint'].forEach((key,i)=>QX_I18N[lang][key]=values[i])}
  const markerRestartLabels={"zh-cn":"界面已更新，后台服务仍是旧版本。请重启收集器并刷新页面后再同步。","zh-tw":"介面已更新，背景服務仍是舊版本。請重新啟動收集器並重新整理頁面後再同步。","en-us":"The interface is newer than the service. Restart the collector and reload before syncing again.","ja-jp":"画面よりサービスが古い状態です。収集ツールを再起動し、ページを再読み込みしてください。","ko-kr":"화면보다 서버 버전이 오래되었습니다. 수집기를 재시작하고 페이지를 새로고침하세요.","es-es":"El servicio es anterior a la interfaz. Reinicia el recolector y recarga la página.","fr-fr":"Le service est plus ancien que l’interface. Redémarrez le collecteur et rechargez la page.","ru-ru":"Сервис старее интерфейса. Перезапустите сборщик и обновите страницу.","th-th":"บริการเป็นรุ่นเก่ากว่าหน้าเว็บ โปรดเริ่มตัวเก็บข้อมูลใหม่และโหลดหน้าอีกครั้ง","vi-vn":"Dịch vụ cũ hơn giao diện. Hãy khởi động lại công cụ và tải lại trang.","de-de":"Der Dienst ist älter als die Oberfläche. Sammler neu starten und Seite neu laden.","id-id":"Layanan lebih lama daripada antarmuka. Mulai ulang pengumpul dan muat ulang halaman.","pt-pt":"O serviço é anterior à interface. Reinicia o coletor e recarrega a página.","tr-tr":"Hizmet arayüzden eski. Toplayıcıyı yeniden başlatıp sayfayı yenileyin.","it-it":"Il servizio è precedente all’interfaccia. Riavvia il raccoglitore e ricarica la pagina."}
